/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"민사 법원(法源)의 순서","줄":[{"t":"민사에 관하여 법률에 규정이 없으면 관습법에 의하고, 관습법이 없으면 조리에 의한다.","src":"민법 제1조"},{"t":"법원 적용 순서: 제정법 → 관습법 → 조리.","src":"민법 제1조"},{"t":"관습법: 사회의 법적 확신(법적 구속력에 대한 확신)을 얻은 관습. 법률의 보충적 효력이 있다.","src":"보충"},{"t":"관습법은 당사자의 주장·증명이 없어도 법원이 직권으로 확정할 수 있다.","src":"기출 2025-1 | 보충"},{"t":"사실인 관습: 법적 확신 없는 관습. 법령 중 선량한 풍속 기타 사회질서에 관계없는 규정(임의규정)과 다른 관습이 있고 당사자의 의사가 명확하지 아니한 때에 그 관습에 의한다.","src":"민법 제106조"},{"t":"사실인 관습은 법원(法源)이 아니다. 법률행위 해석·의사 보충의 자료일 뿐이다.","src":"기출 2025-1 | 보충"},{"t":"사실인 관습은 강행규정(선량한 풍속 기타 사회질서에 관계있는 규정)에 어긋나는 내용으로는 적용되지 않는다.","src":"민법 제106조 | 기출 2025-1"},{"t":"당사자가 임의규정과 다른 의사를 표시한 때에는 그 의사에 의한다.","src":"민법 제105조"},{"t":"미등기 무허가건물의 양수인에게는 소유권에 준하는 관습법상 물권이 인정되지 않는다.","src":"기출 2025-1 | 보충"},{"t":"시효취득한 분묘기지권자: 토지소유자가 분묘기지에 관한 지료를 청구한 날부터의 지료를 지급한다.","src":"기출 2025-1"}]},{"머리":"신의성실의 원칙(제2조 제1항)","줄":[{"t":"권리의 행사와 의무의 이행은 신의에 좇아 성실히 하여야 한다.","src":"민법 제2조 제1항"},{"t":"신의칙 위반은 강행규정 위반이므로 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다.","src":"기출 2022-2 | 기출 2024-1 | 기출 2025-2"},{"t":"신의칙의 파생원칙: 사정변경의 원칙, 실효의 원칙, 모순행위 금지(금반언), 권리남용 금지.","src":"보충"},{"t":"신의칙은 법률관계 당사자가 상대방의 이익을 고려하여 형평에 어긋나거나 신의를 저버리는 내용·방법으로 권리를 행사하거나 의무를 이행하여서는 안 된다는 추상적 규범이다.","src":"기출 2023-2"},{"t":"사정변경의 원칙에서 말하는 사정: 계약의 기초가 된 객관적 사정. 일방 당사자의 주관적·개인적 사정은 아니다.","src":"기출 2024-1"},{"t":"사정변경을 이유로 한 해지: 이사가 재직 중 채무액·변제기가 특정된 회사채무를 보증한 뒤 사임해도 그 보증계약을 일방적으로 해지할 수 없다.","src":"기출 2023-2"},{"t":"실효의 원칙: 권리행사 가능한 권리자가 오랜 기간 행사하지 않아 상대방이 더는 행사하지 않으리라 신뢰할 정당한 사유가 생긴 때 그 후의 권리행사를 막는다. 공법관계인 권력관계에도 적용될 수 있다.","src":"기출 2024-1 | 보충"},{"t":"인지청구권에는 실효의 법리가 적용되지 않는다.","src":"기출 2023-2"},{"t":"신의칙상 부수적 의무(보호의무·안전배려의무): 병원은 입원환자의 휴대품 도난 방지 조치를 강구할 보호의무가 있다.","src":"기출 2022-2"},{"t":"숙박업자는 고객의 안전을 배려할 보호의무를 진다.","src":"기출 2023-2"},{"t":"여행계약의 기획여행업자는 여행자의 안전을 확보하기 위한 합리적 조치를 할 안전배려의무가 있다.","src":"기출 2024-1"},{"t":"유효하게 성립한 계약에 따른 급부의 이행을 청구하는 경우, 법원이 신의칙으로 급부의 일부를 감축하는 것은 원칙적으로 허용되지 않는다.","src":"기출 2022-2"},{"t":"무권대리인이 본인을 단독상속하고 본인의 지위에서 자신이 한 무권대리행위의 추인을 거절하는 것은 신의칙에 반한다.","src":"기출 2022-2 | 기출 2023-21 | 기출 2025-2"},{"t":"소멸시효 완성 후 채무자의 시효 원용(항변권 행사)에도 신의칙이 적용된다. 채권자의 권리행사를 불가능하게 하는 등 특별한 사정이 있으면 원용은 권리남용이 된다.","src":"기출 2025-2 | 보충"},{"t":"법정대리인의 동의 없이 신용구매계약을 체결한 미성년자가 동의 없음을 이유로 계약을 취소하는 것은 신의칙에 반하지 않는다.","src":"기출 2022-2"},{"t":"강행규정을 위반한 약정의 무효를 그 약정을 한 자가 스스로 주장하는 것은 신의칙에 반하지 않는다. 공익적 요구인 합법성의 원칙이 신의칙에 우선한다.","src":"기출 2023-2 | 기출 2023-11 | 기출 2025-2"},{"t":"조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때에는 상대방은 그 조건이 성취되지 아니한 것으로 주장할 수 있다.","src":"민법 제150조 제2항"},{"t":"조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취한 것으로 주장할 수 있다.","src":"민법 제150조 제1항"}]},{"머리":"권리남용 금지(제2조 제2항)","줄":[{"t":"권리는 남용하지 못한다.","src":"민법 제2조 제2항"},{"t":"권리남용 요건: 객관적으로 권리행사로 인한 권리자의 이익과 상대방의 불이익 사이에 현저한 불균형이 있어야 하고, 주관적으로 권리행사의 목적이 상대방에게 고통·손해를 주려는 데 있어야 한다(판례).","src":"기출 2021-2 | 보충"},{"t":"확정판결에 따른 강제집행도 특별한 사정이 있으면 권리남용이 될 수 있다.","src":"기출 2021-2"},{"t":"주로 자기의 채무 이행만을 회피할 목적으로 동시이행항변권을 행사하는 것은 권리남용이 될 수 있다.","src":"기출 2021-2 | 기출 2024-1"},{"t":"토지소유자의 건물 철거 청구가 권리남용이 되어도 토지소유자는 건물 소유자에게 토지 사용대가를 부당이득으로 반환청구할 수 있다.","src":"기출 2021-2"},{"t":"권리남용이 불법행위가 되어 생기는 손해배상청구권: 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년의 시효를 받는다. 1년 단기시효는 없다.","src":"민법 제766조 | 기출 2021-2"}]},{"머리":"권리의 분류와 변동","줄":[{"t":"형성권: 권리자의 일방적 의사표시로 법률관계를 발생·변경·소멸시키는 권리. 취소권·추인권·동의권·해제권·해지권·상계권·상속포기권 등.","src":"기출 2021-1 | 보충"},{"t":"물권적 청구권은 형성권이 아니라 청구권이다.","src":"기출 2021-1"},{"t":"지배권(물권·인격권 등) / 청구권(채권·물권적 청구권) / 형성권 / 항변권(동시이행항변권·보증인의 최고·검색 항변권)으로 나눈다.","src":"보충"},{"t":"원시취득: 타인의 권리에 기초하지 않고 새로 취득. 취득시효, 선의취득, 무주물 선점, 유실물 습득 소유권 취득, 매장물 발견, 부합·혼화·가공, 건물 신축 등.","src":"보충"},{"t":"승계취득: 타인의 권리에 기초한 취득. 이전적 승계(매매·상속 등)와 설정적 승계(지상권·전세권·저당권 설정)가 있다.","src":"보충"},{"t":"타인 소유 부동산에 저당권을 취득하는 것, 보존등기를 마친 자로부터 전세권을 취득하는 것은 설정적 승계취득이다.","src":"기출 2023-12"},{"t":"유실물에 대한 소유권 취득, 점유취득시효 완성에 의한 소유권 취득은 원시취득이다.","src":"기출 2023-12"},{"t":"사람은 생존한 동안 권리와 의무의 주체가 된다.","src":"민법 제3조"}]}],"함정":[{"x":"권리남용이 불법행위가 되어 발생한 손해배상청구권은 1년의 단기소멸시효가 적용된다.","o":"안 날부터 3년, 불법행위를 한 날부터 10년의 시효(제766조)가 적용된다. 1년 단기시효는 없다.","src":"기출 2021-2 | 민법 제766조"},{"x":"법정대리인의 동의 없이 신용구매계약을 체결한 미성년자가 동의 없음을 이유로 계약을 취소하는 것은 신의칙에 반한다.","o":"신의칙에 반하지 않는다. 취소권 행사는 정당한 권리행사이다.","src":"기출 2022-2"},{"x":"사적 자치의 영역을 넘어 공공질서를 위하여 공익적 요구를 선행시켜야 할 경우에도 특별한 사정이 없는 한 신의칙이 합법성의 원칙보다 우월하다.","o":"공익적 요구를 선행시켜야 할 경우에는 합법성의 원칙이 신의칙보다 우선한다.","src":"기출 2023-2"},{"x":"사정변경의 원칙에서의 사정이란 계약을 체결하게 된 일방 당사자의 주관적·개인적 사정을 의미한다.","o":"계약의 기초가 된 객관적 사정을 뜻한다. 일방 당사자의 주관적·개인적 사정은 해당하지 않는다.","src":"기출 2024-1"},{"x":"미등기 무허가건물의 취득자에게는 소유권에 준하는 관습법상의 물권이 있다.","o":"소유권에 준하는 관습법상의 물권은 인정되지 않는다.","src":"기출 2025-1"},{"x":"사실인 관습은 법원(法源)으로서 법령에 저촉되지 않는 한 법칙으로서의 효력이 있다.","o":"법칙으로서 효력이 있는 것은 관습법이다. 사실인 관습은 법원이 아니고 당사자 의사를 보충하는 자료일 뿐이다.","src":"기출 2025-1"},{"x":"관습법은 그 존재를 당사자가 주장·증명하여야 하고, 법원이 직권으로 확정할 수 없다.","o":"관습법은 법원이 직권으로 확정할 수 있다.","src":"기출 2025-1"},{"x":"사실인 관습은 관련 분야의 제정법이 강행규정이라도 특별한 사정이 없는 한 법률행위의 의사를 보충하는 기능으로서 재판의 자료로 할 수 있다.","o":"강행규정에 반하는 사실인 관습은 재판의 자료로 삼을 수 없다. 임의규정과 다른 관습만 의사 보충 기능을 한다.","src":"기출 2025-1 | 민법 제106조"},{"x":"소멸시효를 이유로 한 채무자의 항변권 행사에는 신의성실의 원칙이 적용되지 않는다.","o":"시효 원용에도 신의칙이 적용된다. 특별한 사정이 있으면 원용이 권리남용이 된다.","src":"기출 2025-2"},{"x":"무권대리인이 본인을 단독 상속한 경우, 본인의 지위에서 추인을 거절하더라도 신의성실의 원칙에 반하지 않는다.","o":"신의칙에 반한다.","src":"기출 2025-2"},{"x":"강행규정에 위반하여 계약을 체결한 자가 스스로 그 계약의 무효를 주장하는 것은 특별한 사정이 없는 한 신의성실의 원칙에 반한다.","o":"신의칙에 반하지 않는다.","src":"기출 2025-2"},{"x":"조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시키더라도, 상대방이 그 조건이 성취하지 아니한 것으로 주장할 수는 없다.","o":"상대방은 그 조건이 성취하지 아니한 것으로 주장할 수 있다.","src":"민법 제150조 제2항 | 기출 2025-2"}]},"#2":{"묶음":[{"머리":"성년·미성년자","줄":[{"t":"사람은 19세로 성년에 이르게 된다.","src":"민법 제4조"},{"t":"미성년자가 법률행위를 함에는 법정대리인의 동의를 얻어야 한다. 위반한 행위는 취소할 수 있다.","src":"민법 제5조 제1항·제2항"},{"t":"예외: 권리만을 얻거나 의무만을 면하는 행위는 미성년자가 단독으로 할 수 있다(동의 불필요).","src":"민법 제5조 제1항 | 기출 2021-3 | 기출 2023-6"},{"t":"동의를 요하도록 하는 규정은 강행규정이다.","src":"기출 2024-3"},{"t":"법정대리인의 동의는 묵시적으로도 할 수 있다.","src":"기출 2024-3"},{"t":"법정대리인이 범위를 정하여 처분을 허락한 재산은 미성년자가 임의로 처분할 수 있다.","src":"민법 제6조"},{"t":"처분을 허락한 재산에 관하여도 법정대리인의 대리권은 소멸하지 않는다. 법정대리인은 그 재산에 관하여 유효한 대리행위를 할 수 있다.","src":"보충 | 기출 2023-6"},{"t":"법정대리인은 미성년자가 아직 법률행위를 하기 전에는 동의와 허락을 취소할 수 있다.","src":"민법 제7조"},{"t":"영업의 허락: 미성년자가 법정대리인으로부터 허락을 얻은 특정한 영업에 관하여는 성년자와 동일한 행위능력이 있다.","src":"민법 제8조 제1항"},{"t":"법정대리인은 영업허락을 취소 또는 제한할 수 있다. 그러나 선의의 제3자에게 대항하지 못한다.","src":"민법 제8조 제2항 | 기출 2021-3 | 기출 2024-3"},{"t":"영업이 허락된 범위에서는 법정대리인의 대리권이 없다. 그 영업에 관한 법정대리인의 대리행위는 유효하지 않다.","src":"보충 | 기출 2023-6"},{"t":"법정대리인이 취소한 미성년자의 법률행위는 처음부터 무효인 것으로 본다.","src":"민법 제141조 | 기출 2023-6"},{"t":"미성년자가 법정대리인의 동의 없이 한 법률행위의 취소권자: 미성년자 본인(단독으로 취소 가능), 법정대리인, 그 대리인·승계인.","src":"민법 제140조 | 기출 2021-21"},{"t":"제한능력자도 단독으로 취소권을 행사할 수 있다.","src":"기출 2021-21"}]},{"머리":"성년후견","줄":[{"t":"요건: 질병·장애·노령 그 밖의 사유로 인한 정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람. 일시적 부족자에게는 허용되지 않는다.","src":"민법 제9조 제1항 | 기출 2023-5"},{"t":"청구권자: 본인, 배우자, 4촌 이내의 친족, 미성년후견인, 미성년후견감독인, 한정후견인, 한정후견감독인, 특정후견인, 특정후견감독인, 검사, 지방자치단체의 장.","src":"민법 제9조 제1항"},{"t":"가정법원은 성년후견개시의 심판을 할 때 본인의 의사를 고려하여야 한다.","src":"민법 제9조 제2항 | 기출 2022-4 | 기출 2023-5"},{"t":"피성년후견인의 법률행위는 취소할 수 있다.","src":"민법 제10조 제1항"},{"t":"가정법원은 취소할 수 없는 피성년후견인의 법률행위의 범위를 정할 수 있다.","src":"민법 제10조 제2항 | 기출 2022-4"},{"t":"취소할 수 없는 범위의 변경 청구권자: 본인, 배우자, 4촌 이내의 친족, 성년후견인, 성년후견감독인, 검사, 지방자치단체의 장.","src":"민법 제10조 제3항"},{"t":"일용품의 구입 등 일상생활에 필요하고 그 대가가 과도하지 아니한 법률행위는 성년후견인이 취소할 수 없다.","src":"민법 제10조 제4항 | 기출 2023-5"},{"t":"성년후견종료: 개시 원인이 소멸한 경우 가정법원이 본인, 배우자, 4촌 이내의 친족, 성년후견인, 성년후견감독인, 검사, 지방자치단체의 장의 청구에 의하여 종료 심판을 한다.","src":"민법 제11조"},{"t":"피성년후견인도 의사능력이 있으면 유효하게 임의대리행위를 할 수 있다. 대리인은 행위능력자임을 요하지 않는다.","src":"기출 2024-4 | 민법 제117조"}]},{"머리":"한정후견","줄":[{"t":"요건: 정신적 제약으로 사무를 처리할 능력이 부족한 사람.","src":"민법 제12조 제1항 | 기출 2025-5"},{"t":"한정후견개시 시에도 본인의 의사를 고려하여야 한다(제9조 제2항 준용).","src":"민법 제12조 제2항 | 기출 2025-5"},{"t":"가정법원은 피한정후견인이 한정후견인의 동의를 받아야 하는 행위의 범위를 정할 수 있다.","src":"민법 제13조 제1항 | 기출 2022-4 | 기출 2023-5 | 기출 2025-5"},{"t":"동의 범위 변경 청구권자: 본인, 배우자, 4촌 이내의 친족, 한정후견인, 한정후견감독인, 검사, 지방자치단체의 장.","src":"민법 제13조 제2항 | 기출 2025-5"},{"t":"한정후견인이 피한정후견인의 이익이 침해될 염려가 있음에도 동의하지 않으면 가정법원은 피한정후견인의 청구에 의하여 동의를 갈음하는 허가를 할 수 있다.","src":"민법 제13조 제3항"},{"t":"동의가 필요한 법률행위를 동의 없이 한 때에는 취소할 수 있다. 다만 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 법률행위는 취소할 수 없다.","src":"민법 제13조 제4항 | 기출 2025-5"},{"t":"한정후견종료: 개시 원인이 소멸한 경우 본인, 배우자, 4촌 이내의 친족, 한정후견인, 한정후견감독인, 검사, 지방자치단체의 장의 청구에 의한 심판.","src":"민법 제14조"}]},{"머리":"특정후견","줄":[{"t":"요건: 정신적 제약으로 일시적 후원 또는 특정한 사무에 관한 후원이 필요한 사람.","src":"민법 제14조의2 제1항"},{"t":"청구권자: 본인, 배우자, 4촌 이내의 친족, 미성년후견인, 미성년후견감독인, 검사, 지방자치단체의 장.","src":"민법 제14조의2 제1항 | 기출 2024-4"},{"t":"특정후견은 본인의 의사에 반하여 할 수 없다.","src":"민법 제14조의2 제2항 | 기출 2022-4 | 기출 2024-4"},{"t":"특정후견의 심판을 하는 경우에는 특정후견의 기간 또는 사무의 범위를 정하여야 한다.","src":"민법 제14조의2 제3항 | 기출 2024-4"},{"t":"특정후견은 심판에서 정한 기간이 지나면 종료 심판 없이 종료한다.","src":"기출 2024-4 | 보충"},{"t":"특정후견은 피특정후견인의 행위능력을 제한하지 않는다.","src":"보충"}]},{"머리":"심판 사이의 관계","줄":[{"t":"한정후견·특정후견 중 성년후견개시 심판을 하면 종전 한정후견·특정후견의 종료 심판을 한다.","src":"민법 제14조의3 제1항"},{"t":"성년후견·특정후견 중 한정후견개시 심판을 하면 종전 성년후견·특정후견의 종료 심판을 한다.","src":"민법 제14조의3 제2항 | 기출 2022-4 | 기출 2023-5"}]},{"머리":"제한능력자의 상대방 보호","줄":[{"t":"확답을 촉구할 권리: 능력자가 된 후의 제한능력자에게 1개월 이상의 기간을 정하여 취소할 수 있는 행위의 추인 여부를 촉구한다. 그 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다.","src":"민법 제15조 제1항 | 기출 2023-4"},{"t":"아직 능력자가 되지 못한 경우에는 법정대리인에게 촉구하고, 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다.","src":"민법 제15조 제2항"},{"t":"특별한 절차가 필요한 행위(후견감독인 동의 등)는 기간 내에 그 절차를 밟은 확답을 발송하지 않으면 취소한 것으로 본다.","src":"민법 제15조 제3항"},{"t":"철회권: 제한능력자가 맺은 계약은 추인이 있을 때까지 상대방이 철회할 수 있다. 다만 상대방이 계약 당시에 제한능력자임을 알았던 경우에는 철회할 수 없다.","src":"민법 제16조 제1항 | 기출 2021-3 | 기출 2023-4 | 기출 2024-3"},{"t":"거절권: 제한능력자의 단독행위는 추인이 있을 때까지 상대방이 거절할 수 있다.","src":"민법 제16조 제2항"},{"t":"철회·거절의 의사표시는 제한능력자에게도 할 수 있다.","src":"민법 제16조 제3항 | 기출 2021-3 | 기출 2023-4"},{"t":"속임수: 제한능력자가 속임수로써 자기를 능력자로 믿게 한 경우 그 행위를 취소할 수 없다.","src":"민법 제17조 제1항 | 기출 2025-4"},{"t":"미성년자나 피한정후견인이 속임수로써 법정대리인의 동의가 있는 것으로 믿게 한 경우에도 취소할 수 없다.","src":"민법 제17조 제2항 | 기출 2023-4 | 기출 2023-6 | 기출 2025-4"},{"t":"피성년후견인에 대해서는 제17조 제2항이 적용되지 않는다. 동의가 있는 것처럼 속여도 피성년후견인은 취소할 수 있다.","src":"민법 제17조 제2항 | 기출 2025-4"},{"t":"속임수에 해당하는지는 적극적 기망수단이 있어야 한다. 단순히 자기를 능력자라고 말한 것만으로는 속임수가 아니다.","src":"기출 2025-4 | 보충"},{"t":"속임수를 썼다는 사실의 증명책임은 취소권 배제를 주장하는 상대방에게 있다.","src":"기출 2025-4 | 보충"},{"t":"미성년자가 주민등록증을 변조하여 능력자로 믿게 한 경우 법률행위를 취소할 수 없다.","src":"기출 2023-6"},{"t":"취소의 효과: 취소된 법률행위는 처음부터 무효로 본다. 제한능력자는 현존이익의 한도에서 상환할 책임이 있다(선의·악의 불문).","src":"민법 제141조 | 기출 2024-18"}]},{"머리":"의사능력","줄":[{"t":"의사무능력자의 법률행위는 무효이다.","src":"보충"},{"t":"의사무능력을 이유로 계약이 무효가 된 경우 의사무능력자는 선의·악의를 불문하고 받은 이익이 현존하는 한도에서 반환할 책임이 있다.","src":"기출 2024-2 | 보충"},{"t":"현존이익이 없다는 점의 증명책임은 반환의무자인 의사무능력자(무능력자 쪽)에게 있다. 상대방에게 현존이익의 증명책임이 있는 것이 아니다.","src":"기출 2024-2 | 보충"},{"t":"의사무능력자 쪽(특별대리인 포함)이 의사무능력을 이유로 계약의 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","src":"기출 2024-2 | 보충"}]},{"머리":"주소·거소 등","줄":[{"t":"주소: 생활의 근거되는 곳. 주소는 동시에 두 곳 이상 있을 수 있다.","src":"민법 제18조"},{"t":"주소를 알 수 없으면 거소를 주소로 본다. 국내에 주소 없는 자의 거소도 주소로 본다.","src":"민법 제19조 | 민법 제20조"},{"t":"가주소: 어느 행위에 대해 가주소를 정한 때에는 그 행위에 관하여는 가주소를 주소로 본다.","src":"민법 제21조"},{"t":"2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 추정한다.","src":"민법 제30조"}]}],"함정":[{"x":"법정대리인이 미성년자에게 한 특정한 영업의 허락을 취소하는 경우 그 취소로 선의의 제3자에게 대항할 수 있다.","o":"선의의 제3자에게 대항하지 못한다.","src":"민법 제8조 제2항 | 기출 2021-3"},{"x":"가정법원은 정신적 제약으로 특정한 사무에 관하여 후원이 필요한 자에 대하여는 본인의 의사에 반하더라도 특정후견의 심판을 할 수 있다.","o":"특정후견은 본인의 의사에 반하여 할 수 없다.","src":"민법 제14조의2 제2항 | 기출 2022-4 | 기출 2024-4"},{"x":"성년후견개시의 심판은 정신적 제약으로 사무처리능력이 일시적으로 부족한 사람에게 허용된다.","o":"사무처리능력이 지속적으로 결여된 사람에게 허용된다.","src":"민법 제9조 제1항 | 기출 2023-5"},{"x":"법정대리인이 취소한 미성년자의 법률행위는 취소한 때로부터 그 효력을 상실한다.","o":"취소된 법률행위는 처음부터 무효인 것으로 본다.","src":"민법 제141조 | 기출 2023-6"},{"x":"법정대리인이 재산의 범위를 정하여 미성년자에게 처분을 허락한 경우, 법정대리인은 그 재산에 관하여 유효한 대리행위를 할 수 없다.","o":"처분을 허락한 재산에 관해서도 법정대리인은 유효한 대리행위를 할 수 있다.","src":"기출 2023-6 | 보충"},{"x":"법정대리인이 미성년자에게 특정한 영업을 허락한 경우, 법정대리인은 그 영업에 관하여 유효한 대리행위를 할 수 있다.","o":"영업이 허락된 범위에서는 법정대리인의 대리권이 없어 유효한 대리행위를 할 수 없다.","src":"기출 2023-6 | 보충"},{"x":"미성년자가 오직 권리만을 얻는 법률행위를 할 경우에도 특별한 사정이 없는 한 법정대리인의 동의가 필요하다.","o":"권리만을 얻거나 의무만을 면하는 행위는 동의 없이 단독으로 할 수 있다.","src":"민법 제5조 제1항 | 기출 2023-6"},{"x":"법정대리인의 동의를 요하는 미성년자의 법률행위에 있어서 법정대리인의 동의는 묵시적으로는 할 수 없다.","o":"동의는 묵시적으로도 할 수 있다.","src":"기출 2024-3"},{"x":"가정법원은 본인의 의사에 반하더라도 특정후견의 심판을 할 수 있다.","o":"본인의 의사에 반하여 할 수 없다.","src":"민법 제14조의2 제2항 | 기출 2024-4"},{"x":"질병, 장애, 노령 등으로 인한 정신적 제약 때문에 사무 처리 능력이 지속적으로 결여된 사람을 위한 제도이다(한정후견에 대한 설명으로).","o":"한정후견은 사무처리능력이 부족한 사람을 위한 제도이다. 지속적 결여는 성년후견이다.","src":"민법 제12조 제1항 | 기출 2025-5"}]},"#3":{"묶음":[{"머리":"부재자 재산관리","줄":[{"t":"종래의 주소나 거소를 떠난 자가 재산관리인을 정하지 아니한 때에는 법원은 이해관계인이나 검사의 청구에 의하여 재산관리에 관하여 필요한 처분을 명하여야 한다.","src":"민법 제22조 제1항"},{"t":"본인의 부재 중 재산관리인의 권한이 소멸한 때에도 같다(법원은 필요한 처분을 명하여야 한다).","src":"민법 제22조 제1항 | 기출 2021-4"},{"t":"본인이 그 후에 재산관리인을 정한 때에는 법원은 본인, 재산관리인, 이해관계인 또는 검사의 청구에 의하여 처분명령을 취소하여야 한다.","src":"민법 제22조 제2항"},{"t":"개임: 부재자가 재산관리인을 정한 경우에 생사가 분명하지 아니한 때에는 법원은 재산관리인, 이해관계인 또는 검사의 청구에 의하여 재산관리인을 개임할 수 있다.","src":"민법 제23조 | 기출 2021-4"},{"t":"법원이 선임한 재산관리인은 관리할 재산목록을 작성하여야 한다.","src":"민법 제24조 제1항 | 기출 2021-4 | 기출 2023-1"},{"t":"법원은 선임한 재산관리인에게 부재자 재산을 보존하기 위하여 필요한 처분을 명할 수 있다.","src":"민법 제24조 제2항"},{"t":"부재자의 생사가 분명하지 아니한 경우 이해관계인이나 검사의 청구가 있으면 법원은 부재자가 정한 재산관리인에게도 제1항·제2항의 처분을 명할 수 있다.","src":"민법 제24조 제3항"},{"t":"그 비용은 부재자의 재산으로 지급한다.","src":"민법 제24조 제4항"},{"t":"법원이 선임한 재산관리인이 제118조의 권한(보존행위, 성질을 변하지 않는 범위의 이용·개량행위)을 넘는 행위를 하려면 법원의 허가를 얻어야 한다.","src":"민법 제25조 | 민법 제118조"},{"t":"부재자의 생사가 분명하지 아니한 경우 부재자가 정한 재산관리인이 권한을 넘는 행위를 할 때에도 법원의 허가가 필요하다.","src":"민법 제25조 | 기출 2021-4"},{"t":"부재자가 스스로 재산처분권을 위임한 재산관리인이 재산을 처분하는 경우 생사가 분명하지 않은 때가 아니면 법원의 허가가 필요 없다.","src":"민법 제25조 | 기출 2022-3"},{"t":"보존행위(예: 소유권이전등기말소청구, 시효중단)는 법원의 허가 없이 할 수 있다.","src":"민법 제118조 제1호 | 기출 2023-1 | 기출 2025-3"},{"t":"법원의 허가는 이미 한 처분행위를 사후에 추인하는 방법으로도 할 수 있다.","src":"기출 2022-3 | 기출 2025-3 | 보충"},{"t":"법원은 선임한 재산관리인으로 하여금 재산의 관리 및 반환에 관하여 상당한 담보를 제공하게 할 수 있다.","src":"민법 제26조 제1항 | 기출 2022-3 | 기출 2023-1"},{"t":"법원은 선임한 재산관리인에게 부재자의 재산으로 상당한 보수를 지급할 수 있다.","src":"민법 제26조 제2항 | 기출 2021-4 | 기출 2023-1"},{"t":"제26조 제1항·제2항은 생사가 분명하지 아니한 경우 부재자가 정한 재산관리인에게 준용한다.","src":"민법 제26조 제3항"},{"t":"부재자의 사망이 확인되어도 선임결정이 취소되지 않는 한 법원이 선임한 재산관리인의 권한은 소멸하지 않는다.","src":"기출 2023-1 | 기출 2025-3"}]},{"머리":"실종선고","줄":[{"t":"일반실종: 부재자의 생사가 5년간 분명하지 아니한 때 이해관계인이나 검사의 청구에 의하여 법원은 실종선고를 하여야 한다.","src":"민법 제27조 제1항"},{"t":"특별실종: 전지에 임한 자, 침몰한 선박 중에 있던 자, 추락한 항공기 중에 있던 자 그 밖의 위난을 당한 자의 생사가 전쟁종지·선박침몰·항공기 추락 그 밖의 위난 종료 후 1년간 분명하지 아니한 때.","src":"민법 제27조 제2항"},{"t":"실종선고는 청구권자가 이해관계인 또는 검사이며, 요건이 충족되면 법원은 실종선고를 하여야 한다(필요적).","src":"민법 제27조 | 기출 2023-3"},{"t":"이해관계인은 법률상 이해관계가 있는 자. 부재자의 제1순위 상속인이 있으면 제2순위 상속인은 이해관계인이 아니다.","src":"기출 2022-3 | 기출 2023-3"},{"t":"실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다.","src":"민법 제28조 | 기출 2022-3 | 기출 2023-3"},{"t":"실종선고의 효과는 간주이다. 실종선고가 취소되지 않는 한 반증을 들어 다툴 수 없다.","src":"기출 2023-3 | 보충"},{"t":"실종선고의 효과는 종래의 주소를 중심으로 하는 사법상 법률관계에 한한다. 생존한 실종자가 다른 곳에서 한 법률행위는 유효하다.","src":"보충"},{"t":"취소 요건: 실종자의 생존한 사실 또는 실종기간 만료 시와 다른 때에 사망한 사실의 증명이 있으면 법원은 본인, 이해관계인 또는 검사의 청구에 의하여 실종선고를 취소하여야 한다.","src":"민법 제29조 제1항"},{"t":"실종선고 후 취소 전에 선의로 한 행위의 효력에는 영향이 없다.","src":"민법 제29조 제1항"},{"t":"취소 시 반환: 실종선고를 직접원인으로 재산을 취득한 자가 선의면 받은 이익이 현존하는 한도에서, 악의면 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상한다.","src":"민법 제29조 제2항 | 기출 2023-3"}]}],"함정":[{"x":"부재자가 재산관리인을 정한 경우 부재자의 생사가 분명하지 아니하게 되어 이해관계인이 청구를 하더라도 법원은 그 재산관리인을 개임할 수 없다.","o":"법원은 재산관리인, 이해관계인 또는 검사의 청구에 의하여 재산관리인을 개임할 수 있다.","src":"민법 제23조 | 기출 2021-4"},{"x":"법원이 선임한 부재자 재산관리인의 권한초과행위에 대한 법원의 허가 결정은 기왕의 법률행위를 추인하는 방법으로는 할 수 없다.","o":"사후에 추인하는 방법으로도 허가할 수 있다.","src":"기출 2022-3 | 기출 2025-3"},{"x":"법원이 선임한 재산관리인은 법원의 허가 없이 재산의 보존행위를 할 수 없다.","o":"보존행위는 법원의 허가 없이 할 수 있다.","src":"민법 제118조 제1호 | 민법 제25조 | 기출 2023-1"},{"x":"실종선고가 취소되지 않았더라도 반증을 들어 실종선고의 효과를 다툴 수 있다.","o":"실종선고가 취소되지 않는 한 반증으로 효과를 다툴 수 없다.","src":"기출 2023-3"},{"x":"乙은 법원의 허가가 없으면 부동산 소유권이전등기말소절차의 이행을 청구할 수 없다.","o":"등기말소청구는 보존행위이므로 법원의 허가가 필요 없다.","src":"민법 제118조 제1호 | 기출 2025-3"}]},"#4":{"묶음":[{"머리":"법인의 성립","줄":[{"t":"법인은 법률의 규정에 의함이 아니면 성립하지 못한다(법인법정주의).","src":"민법 제31조 | 기출 2024-5"},{"t":"학술·종교·자선·기예·사교 그 밖의 영리 아닌 사업을 목적으로 하는 사단 또는 재단은 주무관청의 허가를 얻어 법인으로 할 수 있다(허가주의).","src":"민법 제32조 | 기출 2021-7"},{"t":"영리를 목적으로 하는 사단은 상사회사 설립의 조건에 좇아 법인으로 할 수 있고, 상사회사에 관한 규정을 준용한다.","src":"민법 제39조"},{"t":"법인은 그 주된 사무소의 소재지에서 설립등기를 함으로써 성립한다.","src":"민법 제33조 | 기출 2021-7"},{"t":"설립허가가 있으면 3주간 내에 주된 사무소 소재지에서 설립등기를 하여야 한다.","src":"민법 제49조 제1항"},{"t":"법인은 법률의 규정에 좇아 정관으로 정한 목적의 범위 내에서 권리와 의무의 주체가 된다.","src":"민법 제34조 | 기출 2021-7"},{"t":"법인의 주소는 주된 사무소의 소재지에 있는 것으로 한다.","src":"민법 제36조"},{"t":"주무관청은 법인의 사무를 검사·감독한다.","src":"민법 제37조"},{"t":"법인이 목적 이외의 사업을 하거나 설립허가의 조건에 위반하거나 그 밖에 공익을 해하는 행위를 한 때 주무관청은 설립허가를 취소할 수 있다.","src":"민법 제38조"},{"t":"등기사항: 목적, 명칭, 사무소, 설립허가의 연월일, 존립시기나 해산이유를 정한 때 그 시기·사유, 자산의 총액, 출자의 방법을 정한 때 그 방법, 이사의 성명·주소, 이사의 대표권을 제한한 때 그 제한.","src":"민법 제49조 제2항"},{"t":"설립등기 이외의 등기사항은 등기 후가 아니면 제3자에게 대항하지 못한다. 등기한 사항은 법원이 지체 없이 공고한다.","src":"민법 제54조"},{"t":"분사무소 설치·사무소 이전·변경은 3주간(3주일) 내에 등기한다.","src":"민법 제50조 | 민법 제51조 | 민법 제52조"},{"t":"이사의 직무집행을 정지하거나 직무대행자를 선임하는 가처분을 하거나 변경·취소하는 경우 주사무소 소재지 등기소에서 등기한다.","src":"민법 제52조의2"},{"t":"직무대행자는 가처분명령에 다른 정함이 없으면 법인의 통상사무에 속하지 않는 행위를 하지 못한다. 법원의 허가를 얻은 경우는 예외이다. 위반한 행위에도 법인은 선의의 제3자에 대하여 책임을 진다.","src":"민법 제60조의2"},{"t":"법인은 성립한 때 및 매년 3월 내에 재산목록을 작성하여 사무소에 비치하여야 한다. 사업연도를 정한 법인은 성립한 때 및 그 연도 말에 작성한다.","src":"민법 제55조 제1항"},{"t":"사단법인은 사원명부를 비치하고 사원의 변경이 있으면 기재한다.","src":"민법 제55조 제2항"}]},{"머리":"사단법인의 정관","줄":[{"t":"정관의 필요적 기재사항: 목적, 명칭, 사무소의 소재지, 자산에 관한 규정, 이사의 임면에 관한 규정, 사원자격의 득실에 관한 규정, 존립시기나 해산사유를 정하는 때에는 그 시기 또는 사유.","src":"민법 제40조"},{"t":"사단법인의 존립시기·해산사유는 정한 때에만 기재하는 사항이다(필요적 기재사항 중 정한 때에 한한다).","src":"민법 제40조 제7호"},{"t":"사단법인의 정관은 자치법규로서 규범적 성질을 가진다(계약이 아니다).","src":"기출 2025-6 | 보충"},{"t":"이사의 대표권에 대한 제한은 정관에 기재하지 아니하면 그 효력이 없다.","src":"민법 제41조"},{"t":"이사의 대표권에 대한 제한은 등기하지 아니하면 제3자에게 대항하지 못한다. 제3자는 선의·악의를 불문한다.","src":"민법 제60조 | 기출 2022-5 | 기출 2024-7"},{"t":"대표권 제한의 효력은 정관 기재(제41조)와 등기(제60조) 모두 있어야 제3자에게 미친다.","src":"민법 제41조 | 민법 제60조 | 기출 2025-6"},{"t":"정관 변경: 총사원 3분의 2 이상의 동의가 있어야 한다. 정수에 관하여 정관에 다른 규정이 있으면 그에 의한다.","src":"민법 제42조 제1항"},{"t":"정관의 변경은 주무관청의 허가를 얻지 아니하면 효력이 없다. 법원의 허가가 아니다.","src":"민법 제42조 제2항 | 기출 2025-6"},{"t":"사단법인의 사원의 지위는 양도 또는 상속할 수 없다. 다만 정관에 정함이 있으면 상속될 수 있다는 것이 판례이다.","src":"민법 제56조 | 기출 2022-5"}]},{"머리":"재단법인의 설립과 정관","줄":[{"t":"설립자는 일정한 재산을 출연하고 제40조 제1호부터 제5호의 사항을 기재한 정관을 작성하여 기명날인하여야 한다.","src":"민법 제43조"},{"t":"재단법인의 존립시기·해산사유(제40조 제7호)는 필요적 기재사항이 아니다.","src":"민법 제43조 | 기출 2021-7 | 기출 2025-6"},{"t":"정관 보충: 설립자가 명칭, 사무소 소재지 또는 이사 임면의 방법을 정하지 아니하고 사망한 때 이해관계인 또는 검사의 청구에 의하여 법원이 이를 정한다.","src":"민법 제44조 | 기출 2021-7 | 기출 2024-5"},{"t":"재단법인의 정관은 그 변경방법을 정관에 정한 때에 한하여 변경할 수 있다.","src":"민법 제45조 제1항 | 기출 2025-6"},{"t":"재단법인의 목적달성 또는 재산보전을 위하여 적당한 때에는 정관에 변경방법이 없어도 명칭 또는 사무소의 소재지를 변경할 수 있다. 정관변경은 주무관청의 허가를 얻어야 한다.","src":"민법 제45조 제2항·제3항"},{"t":"재단법인의 목적을 달성할 수 없는 때 설립자나 이사는 주무관청의 허가를 얻어 설립의 취지를 참작하여 그 목적 기타 정관의 규정을 변경할 수 있다.","src":"민법 제46조 | 기출 2024-5"},{"t":"생전처분으로 재단법인을 설립하는 때에는 증여에 관한 규정을, 유언으로 설립하는 때에는 유증에 관한 규정을 준용한다.","src":"민법 제47조"},{"t":"출연재산의 귀속시기: 생전처분은 법인이 성립된 때, 유언은 유언의 효력이 발생한 때부터 법인에 귀속한다(법인 성립 시에 법인재산이 된다).","src":"민법 제48조"},{"t":"재단법인의 기본재산을 새롭게 편입하는 행위나 처분하는 행위는 정관변경에 해당하여 주무관청의 허가가 필요하다.","src":"보충 | 기출 2022-5"}]},{"머리":"이사","줄":[{"t":"법인은 이사를 두어야 한다(필수기관).","src":"민법 제57조"},{"t":"이사는 법인의 사무를 집행한다. 이사가 수인인 경우 정관에 다른 규정이 없으면 법인의 사무집행은 이사의 과반수로써 결정한다.","src":"민법 제58조 | 기출 2021-5 | 기출 2024-6"},{"t":"이사는 법인의 사무에 관하여 각자 법인을 대표한다. 그러나 정관의 취지에 위반할 수 없고 특히 사단법인은 총회의 의결에 의하여야 한다.","src":"민법 제59조 제1항"},{"t":"법인의 대표에 관하여는 대리에 관한 규정을 준용한다.","src":"민법 제59조 제2항 | 기출 2021-5"},{"t":"이사는 선량한 관리자의 주의로 그 직무를 행하여야 한다.","src":"민법 제61조"},{"t":"이사가 임무를 해태한 때에는 그 이사는 법인에 대하여 연대하여 손해배상의 책임이 있다.","src":"민법 제65조"},{"t":"이사는 정관 또는 총회의 결의로 금지하지 아니한 사항에 한하여 타인으로 하여금 특정한 행위를 대리하게 할 수 있다(포괄적 위임은 허용되지 않는다).","src":"민법 제62조 | 기출 2021-5 | 기출 2024-6"},{"t":"임시이사: 이사가 없거나 결원이 있는 경우에 이로 인하여 손해가 생길 염려가 있는 때 법원은 이해관계인이나 검사의 청구에 의하여 임시이사를 선임하여야 한다.","src":"민법 제63조 | 기출 2024-6"},{"t":"특별대리인: 법인과 이사의 이익이 상반하는 사항에 관하여 이사는 대표권이 없다. 이 경우 임시이사 선임 규정(제63조)에 의하여 특별대리인을 선임하여야 한다.","src":"민법 제64조 | 기출 2021-5 | 기출 2024-7"},{"t":"임시이사와 특별대리인은 서로 다른 기관이다. 임시이사는 이사 결원 시, 특별대리인은 이익상반 시에 선임한다.","src":"민법 제63조 | 민법 제64조 | 기출 2021-5"},{"t":"이사의 사임은 법인의 대표기관에 대한 일방적 의사표시로 효력이 생기며 주무관청의 승인이 필요 없다.","src":"기출 2024-6 | 보충"},{"t":"법인의 정관에 이사의 해임사유에 관한 규정이 있으면 특별한 사정이 없는 한 정관에서 정하지 아니한 사유로 이사를 해임할 수 없다.","src":"기출 2024-6"}]},{"머리":"감사","줄":[{"t":"법인은 정관 또는 총회의 결의로 감사를 둘 수 있다(임의기관). 재단법인·사단법인 모두 감사는 필수기관이 아니다.","src":"민법 제66조 | 기출 2022-5"},{"t":"감사의 직무: 법인의 재산상황 감사, 이사의 업무집행 상황 감사, 재산상황 또는 업무집행의 부정·불비를 발견한 때 총회 또는 주무관청에 보고, 그 보고를 위하여 필요한 때 총회 소집.","src":"민법 제67조 | 기출 2024-5"},{"t":"감사는 재산상황의 부정을 총회에 보고하기 위하여 필요하면 임시총회를 소집할 권한이 있다.","src":"민법 제67조 제4호 | 기출 2024-5"}]},{"머리":"사단법인의 총회","줄":[{"t":"사단법인의 사무는 정관으로 이사 또는 다른 임원에게 위임한 사항 외에는 총회의 결의에 의하여야 한다.","src":"민법 제68조"},{"t":"통상총회: 이사는 매년 1회 이상 소집하여야 한다.","src":"민법 제69조"},{"t":"임시총회: 이사는 필요하다고 인정한 때 소집할 수 있다. 총사원의 5분의 1 이상이 회의의 목적사항을 제시하여 청구하면 이사는 소집하여야 한다(정수는 정관으로 증감 가능).","src":"민법 제70조 제1항·제2항"},{"t":"청구 후 2주간 내에 이사가 소집절차를 밟지 아니하면 청구한 사원이 법원의 허가를 얻어 소집할 수 있다.","src":"민법 제70조 제3항"},{"t":"총회 소집: 1주간 전에 회의의 목적사항을 기재한 통지를 발하고 그 밖에 정관에 정한 방법에 의한다.","src":"민법 제71조"},{"t":"총회는 통지한 사항에 관하여서만 결의할 수 있다. 정관에 다른 규정이 있으면 그에 의한다.","src":"민법 제72조"},{"t":"각 사원의 결의권은 평등하다. 사원은 서면이나 대리인으로 결의권을 행사할 수 있다. 정관에 다른 규정이 있으면 적용하지 않는다.","src":"민법 제73조"},{"t":"사단법인과 어느 사원과의 관계사항을 의결하는 경우 그 사원은 결의권이 없다.","src":"민법 제74조"},{"t":"총회의 결의는 본법 또는 정관에 다른 규정이 없으면 사원 과반수의 출석과 출석사원의 결의권의 과반수로 한다. 서면·대리인으로 결의권을 행사하는 사원은 출석한 것으로 본다.","src":"민법 제75조"},{"t":"총회의 의사에 관하여는 의사록을 작성하고 의사의 경과·요령·결과를 기재하여 의장 및 출석한 이사가 기명날인한다. 이사는 의사록을 주된 사무소에 비치한다.","src":"민법 제76조"}]}],"함정":[{"x":"재단법인의 존립시기는 정관의 필요적 기재사항이다.","o":"재단법인의 정관에는 제40조 제1호부터 제5호만 필요적 기재사항이다. 존립시기·해산사유는 필요적 기재사항이 아니다.","src":"민법 제43조 | 기출 2021-7 | 기출 2025-6"},{"x":"재단법인의 기본재산을 새롭게 편입하는 행위는 주무관청의 허가를 받지 않아도 유효하다.","o":"기본재산의 편입은 정관변경에 해당하여 주무관청의 허가가 필요하다.","src":"기출 2022-5 | 보충"},{"x":"재단법인의 감사는 민법상 필수기관이다.","o":"감사는 임의기관이다.","src":"민법 제66조 | 기출 2022-5"},{"x":"사단법인이 정관에 이사의 대표권에 관한 제한을 규정한 경우에는 이를 등기하지 않더라도 악의의 제3자에게 대항할 수 있다.","o":"등기하지 않으면 선의·악의를 불문하고 제3자에게 대항하지 못한다.","src":"민법 제60조 | 기출 2022-5"},{"x":"이사 전원의 의결에 의하여 잔여재산을 처분하도록 한 사단법인의 정관 규정은 성질상 등기하여야만 제3자에게 대항할 수 있는 청산인의 대표권에 대한 제한으로 보아야 한다.","o":"청산인의 대표권 제한으로 보지 않는다. 잔여재산 처분은 청산인의 직무로서 청산절차에 따라야 한다.","src":"기출 2022-5"},{"x":"사단법인의 감사는 법인의 재산상황에 관하여 부정한 것이 있음을 발견한 경우, 이를 총회에 보고하기 위해 필요하더라도 임시총회를 소집할 권한은 없다.","o":"감사는 보고를 위하여 필요한 때 총회를 소집할 수 있다.","src":"민법 제67조 제4호 | 기출 2024-5"},{"x":"이사의 사임은 특별한 사정이 없는 한 주무관청의 승인이 있어야 그 효력이 발생한다.","o":"사임에 주무관청의 승인은 필요하지 않다.","src":"기출 2024-6 | 보충"},{"x":"사단법인의 정관은 자치법규가 아니라 계약이다.","o":"사단법인의 정관은 자치법규이다.","src":"기출 2025-6 | 보충"},{"x":"이사의 대표권에 대한 제한은 이를 정관에 기재하지 않더라도 등기하면 효력이 있다.","o":"정관에 기재하지 아니하면 효력이 없다(제41조). 등기는 대항요건이다(제60조).","src":"민법 제41조 | 민법 제60조 | 기출 2025-6"},{"x":"사단법인의 정관 변경은 법원의 허가를 얻지 않으면 효력이 없다.","o":"주무관청의 허가를 얻지 않으면 효력이 없다.","src":"민법 제42조 제2항 | 기출 2025-6"},{"x":"재단법인의 존립시기나 해산사유는 정관의 필요적 기재사항이다.","o":"재단법인의 필요적 기재사항이 아니다.","src":"민법 제43조 | 기출 2025-6"}]},"#5":{"묶음":[{"머리":"법인의 불법행위능력(제35조 제1항)","줄":[{"t":"법인은 이사 기타 대표자가 그 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있다. 이사 기타 대표자는 이로 인하여 자기의 손해배상책임을 면하지 못한다.","src":"민법 제35조 제1항"},{"t":"법인과 대표자 개인은 모두 피해자에게 책임을 진다(법인만 책임지는 것이 아니다).","src":"민법 제35조 제1항 후단 | 기출 2023-7"},{"t":"법인이 배상하면 법인은 대표자에게 구상할 수 있다.","src":"기출 2021-6 | 보충"},{"t":"법인 책임에는 사용자책임(제756조)과 달리 선임·감독에 주의를 다하였다는 면책이 인정되지 않는다.","src":"기출 2021-6 | 보충"},{"t":"성립요건: ① 대표기관(이사 기타 대표자)의 행위 ② 직무에 관한 행위 ③ 일반 불법행위 요건 충족(고의·과실, 위법성, 손해, 인과관계, 책임능력).","src":"민법 제35조 | 보충"},{"t":"대표자 범위: 이사, 임시이사, 특별대리인, 직무대행자, 청산인, 그리고 법인을 사실상 대표하여 사무를 집행하는 자(대표자로 등기되었는지는 묻지 않는다).","src":"기출 2021-6 | 기출 2023-7 | 보충"},{"t":"직무에 관한 행위인지는 행위의 외형상 객관적으로 직무행위로 보이는지로 판단한다. 대표자 개인의 이익을 위한 행위이거나 법령 규정에 위배된 행위라도 외형상 직무행위이면 직무에 관한 행위이다.","src":"기출 2021-6 | 기출 2023-7"},{"t":"대표자의 부정한 대표행위라도 직무범위 내에 있으면 법인의 불법행위가 성립할 수 있다.","src":"기출 2023-7"},{"t":"피해자가 직무행위에 해당하지 아니함을 알았거나 중대한 과실로 알지 못한 때에는 법인에 책임을 물을 수 없다. 경과실로 알지 못한 경우에는 법인에게 책임을 물을 수 있다.","src":"기출 2023-7 | 보충"},{"t":"법인의 목적범위 외의 행위로 타인에게 손해를 가한 때에는 그 사항의 의결에 찬성하거나 그 의결을 집행한 사원·이사 및 기타 대표자가 연대하여 배상한다.","src":"민법 제35조 제2항"},{"t":"대표권 없는 일반 직원의 불법행위는 제35조가 아니라 사용자책임(제756조)의 문제이다.","src":"보충"},{"t":"대표자 포괄 위임: 대표자가 대표자로서의 모든 권한을 타인에게 포괄적으로 위임하면 그 대행행위는 원칙적으로 법인에 효력이 없다(이사의 대리인 선임은 특정한 행위에 한함). 포괄 위임을 받아 실질적으로 대표자로서 사무를 집행하는 자는 사실상 대표자로서 제35조의 책임이 생길 수 있다.","src":"민법 제62조 | 기출 2022-6"},{"t":"비법인사단은 정관에서 대리를 금지한 사항을 포괄적으로 위임할 수 없다.","src":"기출 2022-6 | 보충"}]},{"머리":"대표권","줄":[{"t":"이사는 법인의 사무에 관하여 각자 법인을 대표한다. 정관의 취지에 위반할 수 없고 특히 사단법인은 총회의 의결에 의하여야 한다.","src":"민법 제59조 제1항"},{"t":"법인의 대표에 관하여는 대리에 관한 규정을 준용한다.","src":"민법 제59조 제2항"},{"t":"법인과 이사의 이익이 상반하는 사항에 관하여는 이사는 대표권이 없다. 이 경우 특별대리인을 선임하여야 한다.","src":"민법 제64조 | 기출 2024-7"},{"t":"이사의 대표권에 대한 제한은 정관에 기재하여야 효력이 있고, 등기하지 아니하면 제3자에게 대항하지 못한다(제3자의 선의·악의 불문).","src":"민법 제41조 | 민법 제60조 | 기출 2024-7"},{"t":"대표자가 계약을 체결하고 법인의 채무불이행으로 상대방이 계약을 해제한 경우 원상회복의무는 계약 당사자인 법인이 부담한다. 대표자 개인이 부담하지 않는다.","src":"기출 2024-7 | 보충"},{"t":"법인의 대표자가 매매대금을 법인을 위하여 수령한 경우에도 법적 효과는 법인에 귀속한다.","src":"기출 2024-7"},{"t":"법인의 권리능력은 정관으로 정한 목적의 범위 내이다. 목적 범위는 정관에 명시된 것에 한하지 않고 목적 수행에 직접·간접으로 필요한 행위를 포함하며 객관적으로 판단한다.","src":"민법 제34조 | 보충"},{"t":"대표자가 자기 또는 제3자의 이익을 위하여 대표권을 남용한 경우, 상대방이 그 사정을 알았거나 알 수 있었을 때에는 법인에 효력이 없다(제107조 제1항 단서 유추).","src":"보충"}]}],"함정":[{"x":"乙이 법인을 실질적으로 운영하면서 사실상 대표하여 사무를 집행하였더라도 대표자로 등기되지 않았다면 민법 제35조에서 정한 ‘대표자’에 해당하지 않는다.","o":"등기 여부와 관계없이 사실상 대표하여 사무를 집행한 자도 제35조의 대표자이다.","src":"기출 2021-6"},{"x":"법인의 대표자는 법인을 사실상 대표하는지 여부와 관계없이 대표자로 등기되었는지 여부만을 기준으로 판단하여야 한다.","o":"등기 여부만이 기준이 아니다. 사실상 대표자도 포함된다.","src":"기출 2023-7"},{"x":"법인의 대표자가 부정한 대표행위를 한 경우에 그 행위가 직무범위 내에 있더라도 법인의 불법행위가 성립될 여지가 없다.","o":"직무범위 내이면 법인의 불법행위가 성립할 수 있다.","src":"기출 2023-7"},{"x":"행위의 외형상 법인의 대표자의 직무행위라고 인정되더라도 법령의 규정에 위배된 것이라면 직무에 관한 행위에 해당하지 않는다.","o":"법령에 위배된 행위도 외형상 직무행위이면 직무에 관한 행위이다.","src":"기출 2023-7"},{"x":"법인의 대표자의 행위로 법인의 불법행위책임이 성립하는 경우, 특별한 사정이 없는 한 법인만이 피해자에게 불법행위책임을 진다.","o":"대표자 개인도 자기의 손해배상책임을 면하지 못한다.","src":"민법 제35조 제1항 | 기출 2023-7"},{"x":"만약 甲이 비법인사단이라면 乙은 甲의 사무 중 정관에서 대리를 금지한 사항의 처리에 대해서도 丙에게 포괄적으로 위임할 수 있다.","o":"정관에서 대리를 금지한 사항은 포괄적으로 위임할 수 없다.","src":"기출 2022-6"},{"x":"甲이 A를 위하여 매수인 乙로부터 매매대금을 수령한 경우에 A의 채무불이행을 이유로 乙이 매매계약을 유효하게 해제하면, 특별한 사정이 없는 한 해제로 인한 원상회복의무는 甲이 부담한다.","o":"원상회복의무는 계약 당사자인 법인 A가 부담한다.","src":"기출 2024-7"},{"x":"만약 A가 정관에 甲의 매매계약체결에 관한 대표권을 제한하는 규정을 두었지만 이를 등기하지 않은 경우, A는 이러한 사실을 알았던 乙에게 그 대표권 제한사실로써 대항할 수 있다.","o":"등기하지 않으면 제3자가 알았더라도 대항하지 못한다.","src":"민법 제60조 | 기출 2024-7"}]},"#6":{"묶음":[{"머리":"해산","줄":[{"t":"법인의 해산사유: 존립기간의 만료, 법인의 목적의 달성 또는 달성의 불능, 그 밖에 정관에 정한 해산사유의 발생, 파산, 설립허가의 취소.","src":"민법 제77조 제1항"},{"t":"사단법인의 추가 해산사유: 사원이 없게 된 때, 총회의 결의.","src":"민법 제77조 제2항 | 기출 2025-8"},{"t":"사단법인은 총사원 4분의 3 이상의 동의가 없으면 해산을 결의하지 못한다. 정관에 다른 규정이 있으면 그에 의한다.","src":"민법 제78조 | 기출 2022-7"},{"t":"법인이 채무를 완제하지 못하게 된 때 이사는 지체 없이 파산신청을 하여야 한다.","src":"민법 제79조"},{"t":"잔여재산의 귀속: ① 정관으로 지정한 자 ② 지정이 없거나 지정방법이 없으면 이사 또는 청산인이 주무관청의 허가를 얻어 법인의 목적과 유사한 목적을 위하여 처분(사단법인은 총회의 결의 필요) ③ 처분되지 않은 재산은 국고에 귀속.","src":"민법 제80조"}]},{"머리":"청산","줄":[{"t":"해산한 법인은 청산의 목적 범위 내에서만 권리가 있고 의무를 부담한다(청산법인).","src":"민법 제81조 | 기출 2022-7"},{"t":"청산인: 법인이 해산한 때에는 파산의 경우를 제외하고 이사가 청산인이 된다. 정관 또는 총회의 결의로 달리 정한 바가 있으면 그에 의한다.","src":"민법 제82조 | 기출 2025-8"},{"t":"법원의 청산인 선임: 청산인이 될 자가 없거나 결원으로 손해가 생길 염려가 있는 때 법원이 직권 또는 이해관계인·검사의 청구로 선임할 수 있다.","src":"민법 제83조"},{"t":"법원의 청산인 해임: 중요한 사유가 있는 때 법원이 직권 또는 이해관계인·검사의 청구로 해임할 수 있다.","src":"민법 제84조"},{"t":"해산등기: 청산인은 파산으로 해산한 경우가 아니면 취임 후 3주일 내에 해산 사유와 해산 연월일, 청산인의 성명·주소, 청산인의 대표권을 제한한 경우 그 제한을 주사무소 소재지에서 등기한다.","src":"민법 제85조 제1항"},{"t":"해산신고: 청산인은 파산의 경우를 제외하고 취임 후 3주간 내에 제85조 제1항의 사항을 주무관청에 신고한다. 청산 중 취임한 청산인은 성명·주소만 신고한다.","src":"민법 제86조"},{"t":"청산인의 직무: ① 현존사무의 종결 ② 채권의 추심 및 채무의 변제 ③ 잔여재산의 인도. 직무를 행하기 위하여 필요한 모든 행위를 할 수 있다.","src":"민법 제87조"},{"t":"채권신고의 공고: 청산인은 취임한 날부터 2월 내에 3회 이상의 공고로 채권자에게 일정한 기간 내에 채권을 신고할 것을 최고하여야 한다. 신고기간은 2월 이상이어야 한다.","src":"민법 제88조 제1항"},{"t":"공고에는 채권자가 기간 내에 신고하지 아니하면 청산에서 제외될 것을 표시하여야 한다. 공고는 법원의 등기사항 공고와 동일한 방법으로 한다.","src":"민법 제88조 제2항·제3항"},{"t":"청산인은 알고 있는 채권자에게 각각 채권신고를 최고하여야 한다. 알고 있는 채권자는 청산에서 제외하지 못한다.","src":"민법 제89조 | 기출 2025-8"},{"t":"청산인은 채권신고기간 내에는 채권자에게 변제하지 못한다. 그러나 법인은 채권자에 대한 지연손해배상의무를 면하지 못한다.","src":"민법 제90조 | 기출 2022-7"},{"t":"청산 중의 법인은 변제기에 이르지 아니한 채권에 대하여도 변제할 수 있다. 조건 있는 채권, 존속기간이 불확정한 채권, 가액이 불확정한 채권은 법원이 선임한 감정인의 평가에 의하여 변제한다.","src":"민법 제91조 | 기출 2022-7"},{"t":"청산에서 제외된 채권자는 법인의 채무를 완제한 후 귀속권리자에게 인도하지 아니한 재산에 대하여서만 변제를 청구할 수 있다.","src":"민법 제92조"},{"t":"청산 중 법인의 재산이 채무를 완제하기에 부족함이 분명하게 된 때 청산인은 지체 없이 파산선고를 신청하고 공고하여야 한다. 청산인은 파산관재인에게 사무를 인계함으로써 임무가 종료된다.","src":"민법 제93조"},{"t":"청산이 종결한 때 청산인은 3주간 내에 등기하고 주무관청에 신고하여야 한다.","src":"민법 제94조"},{"t":"법인의 해산 및 청산은 법원이 검사·감독한다(설립은 주무관청).","src":"민법 제95조"},{"t":"청산인에게 준용되는 규정: 제58조 제2항(과반수 결정), 제59조~제62조(대표권, 제한 등기, 직무대행자, 주의의무, 대리인 선임), 제64조(특별대리인), 제65조(임무해태), 제70조(임시총회).","src":"민법 제96조"},{"t":"청산종결등기가 마쳐진 경우에도 청산사무가 종료되지 않았다면 그 범위에서 청산법인으로 존속한다.","src":"기출 2024-5 | 기출 2025-8"},{"t":"민법상 청산절차에 관한 규정은 강행규정이다. 이에 반하는 잔여재산의 처분행위는 특별한 사정이 없는 한 무효이다.","src":"기출 2022-7 | 기출 2025-8"},{"t":"이사 등의 과태료(500만원 이하): 등기 해태, 재산목록·사원명부 부정기재, 검사·감독 방해, 사실 아닌 신고, 제76조·제90조 위반, 파산신청 해태, 공고 해태·부정공고.","src":"민법 제97조"}]},{"머리":"비법인사단","줄":[{"t":"비법인사단: 법인 아닌 사단. 단체성(규약, 대표 방법, 총회 의결, 구성원 변경에도 단체 존속)을 갖춘 실체이다. 법인격은 없으나 소송상 당사자능력이 있다.","src":"보충"},{"t":"비법인사단의 재산은 구성원의 총유이다. 총유물의 관리·처분은 사원총회의 결의에 의한다. 각 사원은 정관 기타 규약에 좇아 총유물을 사용·수익할 수 있다.","src":"민법 제275조 | 민법 제276조 | 보충"},{"t":"총유물에 관한 사원의 권리의무는 사원의 지위의 취득·상실로 취득·상실된다.","src":"민법 제277조"},{"t":"총유물의 매매계약 체결은 총유물의 처분행위에 해당하여 사원총회의 결의가 필요하다.","src":"기출 2023-8 | 보충"},{"t":"구성원은 지분권에 기하여 총유물의 보존행위를 할 수 없다(비법인사단 자체가 하여야 한다).","src":"기출 2023-8 | 보충"},{"t":"비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물의 관리·처분행위가 아니다.","src":"기출 2023-8"},{"t":"비법인사단에는 대표권 제한의 등기에 관한 규정(제60조)이 적용되지 않는다.","src":"기출 2023-8 | 기출 2025-7"},{"t":"법인에 관한 규정 중 임시이사(제63조), 권리능력(제34조), 청산인(제82조), 대표자의 불법행위책임(제35조 제1항)은 비법인사단에 유추적용된다. 제60조(대표권 제한의 등기)는 유추적용되지 않는다.","src":"기출 2025-7 | 보충"},{"t":"교회가 의결권 있는 교인 3분의 2 이상의 찬성으로 소속 교단을 탈퇴한 경우 종전 교회의 재산은 탈퇴한 교회 소속 교인들의 총유로 귀속된다.","src":"기출 2023-8 | 보충"},{"t":"사원권의 상속 여부 등은 정관에 정한 바에 따른다. 법인의 사원권 양도·상속 금지 규정(제56조)은 정관에서 달리 정할 수 있다.","src":"민법 제56조 | 기출 2022-5 | 보충"}]}],"함정":[{"x":"법인의 청산인은 채권신고기간 내에는 채권자에 대하여 변제하지 못하므로 법인은 그 기간 동안의 지연손해배상의무를 면한다.","o":"법인은 지연손해배상의무를 면하지 못한다.","src":"민법 제90조 | 기출 2022-7"},{"x":"비법인사단이 총유물에 관한 매매계약을 체결하는 행위는 총유물의 처분행위가 아니다.","o":"총유물의 처분행위에 해당한다.","src":"기출 2023-8"},{"x":"교회가 의결권을 가진 교인 2/3 이상의 찬성으로 소속 교단을 탈퇴한 경우, 종전 교회의 재산은 탈퇴한 교회 소속 교인들의 총유로 귀속되지 않는다.","o":"탈퇴한 교회 소속 교인들의 총유로 귀속된다.","src":"기출 2023-8"},{"x":"비법인사단의 구성원은 지분권에 기하여 총유물의 보존행위를 할 수 있다.","o":"구성원은 총유물의 보존행위를 단독으로 할 수 없다.","src":"기출 2023-8"},{"x":"비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물의 관리·처분행위로 볼 수 있다.","o":"총유물의 관리·처분행위로 볼 수 없다.","src":"기출 2023-8"},{"x":"청산인은 채권자에 대하여 채권신고를 최고해야 하고, 알고 있는 채권자는 청산에서 제외할 수 있다.","o":"알고 있는 채권자는 청산에서 제외하지 못한다.","src":"민법 제89조 | 기출 2025-8"},{"x":"이사의 대표권에 대한 제한의 대항요건을 규정한 민법 제60조는 비법인사단에 유추적용할 수 있다.","o":"제60조는 비법인사단에 유추적용할 수 없다. 비법인사단에는 대표권 제한의 등기 규정이 적용되지 않는다.","src":"기출 2025-7 | 기출 2023-8"}]},"#7":{"묶음":[{"머리":"물건과 부동산·동산","줄":[{"t":"물건: 유체물 및 전기 기타 관리할 수 있는 자연력.","src":"민법 제98조 | 기출 2021-8 | 기출 2023-9"},{"t":"토지 및 그 정착물은 부동산이다. 부동산 이외의 물건은 동산이다.","src":"민법 제99조"},{"t":"관리할 수 있는 자연력과 금전은 동산이다.","src":"민법 제99조 제2항 | 기출 2021-8"},{"t":"건물은 토지와 별개의 독립한 부동산이다. 최소한의 기둥과 지붕 및 주벽이 있으면 독립한 건물로 인정될 수 있다.","src":"기출 2023-9 | 보충"},{"t":"타인의 토지에 권원 없이 식재한 수목의 소유권은 토지에 부합되어 토지 소유자에게 속한다.","src":"기출 2023-9 | 보충"},{"t":"분묘에 안치된 선조의 유골은 제사주재자에게 승계된다.","src":"기출 2021-8 | 민법 제1008조의3"},{"t":"피상속인이 유언으로 유골의 매장장소를 지정하더라도 제사주재자는 그에 따를 법률적 의무를 지지 않는다.","src":"기출 2022-8 | 보충"}]},{"머리":"주물과 종물","줄":[{"t":"종물의 정의: 물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 이에 부속하게 한 때 그 부속물.","src":"민법 제100조 제1항"},{"t":"종물의 요건: ① 주물의 상용에 공할 것(주물 자체의 효용에 이바지) ② 주물에 부속된 관계(장소적 밀접성) ③ 독립한 물건일 것 ④ 주물과 종물이 동일한 소유자에 속할 것.","src":"민법 제100조 제1항 | 보충"},{"t":"주물의 구성부분은 종물이 될 수 없다.","src":"기출 2024-8 | 보충"},{"t":"독립한 물건이면 부동산도 종물이 될 수 있다.","src":"기출 2024-8 | 보충"},{"t":"주물 소유자의 상용에 공여되고 있더라도 주물 자체의 효용과 관계가 없는 물건은 종물이 아니다.","src":"기출 2022-8 | 기출 2025-9"},{"t":"주유소의 주유기는 특별한 사정이 없는 한 주유소 건물의 종물이다.","src":"기출 2023-9"},{"t":"종물은 주물의 처분에 따른다.","src":"민법 제100조 제2항"},{"t":"주물과 종물은 각각 독립한 물건이다. 법률상 하나의 물건으로 취급되지 않는다.","src":"기출 2025-9 | 보충"},{"t":"제100조 제2항은 임의규정이다. 당사자는 주물을 처분할 때 특약으로 종물을 제외하거나 종물만을 별도로 처분할 수 있다.","src":"기출 2022-8 | 기출 2024-8 | 기출 2025-9"},{"t":"제100조 제2항의 처분에는 공법상 처분도 포함된다. 주물의 권리관계가 공법상 처분에 의하여 생긴 경우에도 적용된다.","src":"기출 2022-8 | 기출 2025-9 | 보충"},{"t":"주물과 종물의 법리는 주된 권리와 종된 권리 상호간에도 유추적용된다.","src":"기출 2025-9 | 보충"},{"t":"주물을 점유에 의하여 시효취득하여도 종물을 점유하지 않았다면 그 효력은 종물에 미치지 않는다.","src":"기출 2021-8 | 기출 2024-8"},{"t":"종물은 주물의 처분 당시 존재하여야 하며, 저당권의 효력은 설정행위에 다른 약정이 없으면 종물에 미친다.","src":"민법 제358조 | 보충"}]},{"머리":"과실","줄":[{"t":"천연과실: 물건의 용법에 의하여 수취하는 산출물.","src":"민법 제101조 제1항 | 기출 2023-9"},{"t":"법정과실: 물건의 사용대가로 받는 금전 기타의 물건(임료·이자 등).","src":"민법 제101조 제2항 | 기출 2024-8"},{"t":"과실은 물건에서 생기는 것이다. 권리의 과실은 민법상 과실이 아니다.","src":"기출 2021-8 | 보충"},{"t":"천연과실은 원물로부터 분리하는 때에 이를 수취할 권리자에게 속한다.","src":"민법 제102조 제1항"},{"t":"법정과실은 수취할 권리의 존속기간 일수의 비율로 취득한다.","src":"민법 제102조 제2항"},{"t":"원본채권이 양도되더라도 이미 변제기에 도달한 지분적 이자채권은 특별한 사정이 없는 한 당연히 함께 양도되지 않는다.","src":"기출 2022-8 | 보충"}]}],"함정":[{"x":"원본채권이 양도되면 특별한 사정이 없는 한 이미 변제기에 도달한 이자채권도 당연히 함께 양도된다.","o":"이미 변제기에 도달한 이자채권은 당연히 함께 양도되지 않는다.","src":"기출 2022-8"},{"x":"주물을 처분할 때 종물을 제외하거나 종물만을 별도로 처분하는 특약은 무효이다.","o":"특약은 유효하다. 제100조 제2항은 임의규정이다.","src":"기출 2022-8 | 기출 2025-9"},{"x":"피상속인이 유언으로 자신의 유골의 매장장소를 지정한 경우, 제사주재자는 피상속인의 의사에 따를 법률적 의무를 부담한다.","o":"제사주재자는 그에 따를 법률적 의무를 부담하지 않는다.","src":"기출 2022-8"},{"x":"‘종물은 주물의 처분에 따른다’고 규정한 민법 제100조 제2항의 ‘처분’에는 공법상 처분은 포함되지 않는다.","o":"공법상 처분도 포함된다.","src":"기출 2022-8"},{"x":"타인의 토지 위에 권원 없이 식재한 수목의 소유권은 특별한 사정이 없는 한 식재한 자에게 속한다.","o":"토지에 부합되어 토지 소유자에게 속한다.","src":"기출 2023-9"},{"x":"주물의 구성부분도 종물이 될 수 있다.","o":"주물의 구성부분은 종물이 될 수 없다. 독립한 물건이어야 한다.","src":"기출 2024-8"},{"x":"독립한 물건이라도 부동산은 종물이 될 수 없다.","o":"독립한 물건이면 부동산도 종물이 될 수 있다.","src":"기출 2024-8"},{"x":"주물에 대한 점유시효취득의 효력은 점유하지 않는 종물에도 미친다.","o":"점유하지 않는 종물에는 미치지 않는다.","src":"기출 2024-8"},{"x":"천연과실은 물건의 사용대가로 받는 금전 기타의 물건을 말한다.","o":"물건의 사용대가로 받는 것은 법정과실이다. 천연과실은 물건의 용법에 의하여 수취하는 산출물이다.","src":"민법 제101조 | 기출 2024-8"},{"x":"주물과 종물은 동일한 소유자에 속한 것으로 법률상 하나의 물건으로 취급된다.","o":"각각 독립한 물건이다.","src":"기출 2025-9"},{"x":"주물을 처분할 때 특약으로 종물을 제외할 수 없고 종물만을 별도로 처분할 수도 없다.","o":"특약으로 종물을 제외할 수 있고 종물만 별도로 처분할 수도 있다.","src":"기출 2025-9"},{"x":"주물과 종물의 관계에 관한 법리는 주된 권리와 종된 권리 상호간에는 적용되지 않는다.","o":"주된 권리와 종된 권리 사이에도 유추적용된다.","src":"기출 2025-9"},{"x":"종물은 주물의 처분에 따른다는 법률효과는 주물의 권리관계가 공법상 처분에 의하여 생긴 경우에는 적용되지 않는다.","o":"공법상 처분에 의하여 생긴 경우에도 적용된다.","src":"기출 2025-9"},{"x":"권리의 과실(果實)은 민법상 과실(果實)이다(2021-8 선지 5).","o":"권리의 과실은 민법상 과실이 아니다. 과실은 물건에서 생긴다.","src":"기출 2021-8"}]},"#8":{"묶음":[{"머리":"법률행위와 사적 자치","줄":[{"t":"법률행위의 자유(계약의 자유)는 사적 자치의 주요한 발현 형식이다.","src":"기출 2025-10"},{"t":"계약은 청약과 승낙의 의사표시가 합치하여 성립하는 법률행위이다.","src":"기출 2025-10"},{"t":"단독행위는 법률행위의 일종으로 법률효과를 발생시키는 법률요건이다.","src":"기출 2025-10"},{"t":"법률행위의 종류: 단독행위(취소·추인·상계·해제·유언·소유권 포기 등) / 계약 / 합동행위.","src":"보충"},{"t":"법정해제권의 행사, 상계, 유언, 소유권의 포기는 단독행위이다. 사인증여는 단독행위가 아니라 계약이다.","src":"기출 2025-11 | 보충"},{"t":"법률효과 발생에 의사표시가 필수적인 것은 유언이다. 상속은 법률의 규정에 의하여 효과가 발생하며 의사표시가 필수적이지 않다.","src":"기출 2025-10 | 보충"},{"t":"준법률행위(의사표시 아닌 것): 관념의 통지(채무의 승인, 채권양도의 통지, 사원총회소집 통지 등), 의사의 통지(최고·거절 등), 감정의 표시. 법률효과는 법률의 규정에 의해 발생한다.","src":"기출 2023-10 | 보충"},{"t":"무권대리인의 상대방이 본인에게 하는 추인 여부의 확답 최고는 의사의 통지로서 준법률행위이다.","src":"기출 2023-10"},{"t":"매매계약의 해제는 법률행위(단독행위)이다. 준법률행위가 아니다.","src":"기출 2023-10"},{"t":"그 밖의 구분: 채권행위/물권행위, 처분행위/의무부담행위, 요식행위/불요식행위, 유인행위/무인행위, 유상행위/무상행위, 생전행위/사후행위.","src":"보충"}]},{"머리":"법률행위의 해석","줄":[{"t":"자연적 해석: 표의자의 내심의 진의를 탐구한다. 당사자 쌍방이 모두 같은 의사로 어느 목적물을 정했으나 표시를 착오한 경우 그 일치한 의사대로 계약이 성립한다(오표시무해의 원칙).","src":"기출 2023-15 | 보충"},{"t":"규범적 해석: 상대방이 합리적으로 이해한 의미(표시의 객관적 의미)에 따른다.","src":"보충"},{"t":"보충적 해석: 법률행위에 흠결이 있을 때 당사자의 가정적 의사, 임의규정, 관습, 신의칙으로 보충한다.","src":"보충"},{"t":"임의규정과 다른 의사표시가 있으면 그에 의한다. 임의규정과 다른 관습이 있는 경우 당사자의 의사가 명확하지 아니한 때에는 그 관습에 의한다.","src":"민법 제105조 | 민법 제106조"}]},{"머리":"의사표시의 효력발생","줄":[{"t":"상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생긴다(도달주의).","src":"민법 제111조 제1항 | 기출 2022-10"},{"t":"도달: 상대방이 의사표시를 알 수 있는 객관적 상태에 놓인 것을 말한다. 상대방이 실제로 읽었는지는 묻지 않는다.","src":"보충"},{"t":"의사표시자가 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향이 없다.","src":"민법 제111조 제2항 | 기출 2022-10"},{"t":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자이면 의사표시자는 그 의사표시로써 대항할 수 없다. 다만 상대방의 법정대리인이 도달 사실을 안 후에는 대항할 수 있다.","src":"민법 제112조 | 기출 2022-10"},{"t":"행위능력을 갖춘 미성년자에게는 특별한 사정이 없는 한 의사표시의 수령능력이 인정된다.","src":"기출 2022-10 | 보충"},{"t":"공시송달: 표의자가 과실 없이 상대방을 알지 못하거나 상대방의 소재를 알지 못하는 경우 민사소송법 공시송달 규정에 의하여 송달할 수 있다.","src":"민법 제113조 | 기출 2022-10"},{"t":"청약의 의사표시는 그 표시가 상대방에게 도달한 때에 효력이 생긴다.","src":"민법 제111조 제1항 | 기출 2022-10"}]}],"함정":[{"x":"의사표시자가 청약의 의사표시를 발송한 후 사망하였다면, 그 의사표시는 처음부터 무효인 것으로 본다.","o":"발송 후 사망하여도 의사표시의 효력에 영향이 없다.","src":"민법 제111조 제2항 | 기출 2022-10"},{"x":"법률행위인 유언과 상속은 법률효과의 발생에 의사표시가 필수적이라는 점에서 공통점이 있다.","o":"유언은 의사표시가 필수적이나 상속은 법률 규정에 의해 효과가 생기며 의사표시가 필수적이지 않다.","src":"기출 2025-10"},{"x":"사인증여는 단독행위이다(2025-11 선지 3).","o":"사인증여는 계약(증여)이므로 단독행위가 아니다.","src":"기출 2025-11"}]},"#9":{"묶음":[{"머리":"목적의 요건과 강행규정","줄":[{"t":"법률행위의 목적 요건: 확정, 가능, 적법, 사회적 타당성.","src":"보충"},{"t":"임의규정(선량한 풍속 기타 사회질서에 관계없는 규정)과 다른 의사를 표시한 때에는 그 의사에 의한다.","src":"민법 제105조"},{"t":"강행규정을 위반한 법률행위는 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다.","src":"기출 2023-11"},{"t":"강행규정 위반으로 확정적 무효가 된 법률행위는 당사자의 추인으로 유효하게 할 수 없다.","src":"기출 2023-11 | 기출 2021-20"},{"t":"강행규정에 위반하여 무효인 계약에는 상대방이 선의·무과실이더라도 표현대리의 법리가 적용되지 않는다.","src":"기출 2023-11 | 기출 2021-19"},{"t":"강행규정을 위반한 약정을 한 자가 스스로 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","src":"기출 2023-11 | 기출 2025-2"},{"t":"법률의 금지에 위반되는 행위라도 선량한 풍속 기타 사회질서에 위반하지 않으면 제746조의 불법원인에 해당하지 않는다.","src":"기출 2023-11"}]},{"머리":"반사회질서의 법률행위(제103조)","줄":[{"t":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다.","src":"민법 제103조"},{"t":"반사회질서 법률행위는 절대적 무효이다. 무효를 선의의 제3자에게도 대항할 수 있다.","src":"기출 2024-17 | 보충"},{"t":"판단 시점은 법률행위가 이루어진 때이다. 동기의 불법은 동기가 표시되거나 상대방에게 알려진 경우 문제된다.","src":"보충"},{"t":"불법원인급여: 불법의 원인으로 재산을 급여하거나 노무를 제공한 때에는 그 이익의 반환을 청구하지 못한다. 불법원인이 수익자에게만 있는 때는 반환을 청구할 수 있다.","src":"민법 제746조"},{"t":"반사회질서에 해당하는 것: 형사사건에서 변호사 성공보수 약정(형사사건 성공보수), 이중매매에 제2매수인이 적극 가담한 매매·증여, 수사기관·법정에서 허위 진술의 대가로 금품을 주기로 한 약정, 부부간 어떠한 일이 있어도 이혼하지 않겠다는 합의, 살인을 조건으로 한 증여, 살인을 포기할 것을 조건으로 한 증여, 도박자금에 제공할 목적의 금전대차, 성매매 전제의 선불금 대여, 보험금 부정취득 목적의 다수 보험계약·보험사고 가장 목적의 생명보험계약, 진정서를 낸 뒤 취하를 조건으로 거액의 급부를 받기로 한 약정.","src":"기출 2021-9 | 기출 2022-17 | 기출 2023-13 | 기출 2024-9 | 기출 2025-12"},{"t":"소송에서 사실대로 증언하는 대가로 통상 허용되는 한도를 넘는 거액을 받기로 한 약정은 반사회질서이다.","src":"기출 2025-12"},{"t":"반사회질서에 해당하지 않는 것: 강제집행을 면하려는 허위 근저당권설정등기(통정허위표시의 문제), 반사회적 행위로 조성된 비자금을 소극적으로 은닉하기 위한 임치, 해외 파견 교육연수를 받은 근로자가 일정 기간 근무하기로 한 약정, 전통사찰 주지직 양도 약정을 알고도 묵인하고 한 주지 임명행위.","src":"기출 2022-17 | 기출 2023-13 | 기출 2024-9 | 기출 2025-12"},{"t":"이중매매: 매도인의 배임행위에 제2매수인이 적극 가담한 때 제2매매는 무효이다. 제2매수인으로부터 취득한 제3자는 선의라도 보호되지 않는다.","src":"기출 2021-9 | 기출 2024-15 | 보충"}]},{"머리":"불공정한 법률행위(제104조)","줄":[{"t":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다.","src":"민법 제104조"},{"t":"요건: 객관적으로 급부와 반대급부 사이에 현저한 불균형이 있고, 주관적으로 피해 당사자의 궁박·경솔·무경험 중 어느 하나가 있으며, 상대방이 이를 알고 이용하려는 의사가 있어야 한다.","src":"기출 2024-10 | 보충"},{"t":"궁박, 경솔, 무경험은 그 중 일부만 갖추어져도 충분하다.","src":"기출 2024-10"},{"t":"궁박: 급박한 곤궁. 경제적 원인뿐 아니라 심리적 원인에 기인할 수도 있다.","src":"기출 2022-13 | 기출 2024-10"},{"t":"무경험: 어느 특정 영역에서의 경험부족이 아니라 거래일반에 대한 경험부족.","src":"기출 2024-10"},{"t":"현저한 불균형이 있어도 궁박·경솔·무경험이 추정되지 않는다.","src":"기출 2022-13 | 보충"},{"t":"불공정 여부는 법률행위가 이루어진 시점을 기준으로 약속된 급부와 반대급부의 객관적 가치를 비교하여 판단한다.","src":"기출 2024-10"},{"t":"대리인이 한 법률행위: 경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다.","src":"기출 2022-13 | 기출 2024-15 | 보충"},{"t":"무상행위(증여 등 대가 관계 없는 행위)는 불공정한 법률행위의 대상이 아니다.","src":"기출 2025-13 | 보충"},{"t":"경매에는 제104조가 적용되지 않는다.","src":"기출 2024-10 | 기출 2025-13 | 보충"},{"t":"불공정한 법률행위로 무효인 경우 추인에 의해 유효가 될 수 없다. 그 계약에 대한 부제소합의도 무효이다.","src":"기출 2021-20 | 기출 2022-13 | 기출 2023-18 | 기출 2025-13 | 보충"},{"t":"불공정한 법률행위에도 무효행위의 전환(제138조)이 적용될 여지가 있다.","src":"기출 2022-13 | 기출 2023-18 | 기출 2025-13 | 보충"},{"t":"불공정한 법률행위의 무효는 선의의 제3자에게도 대항할 수 있다.","src":"기출 2025-13 | 보충"}]}],"함정":[{"x":"살인을 포기할 것을 조건으로 한 증여는 반사회적 법률행위가 아니다.","o":"반사회적 법률행위이다.","src":"기출 2021-9"},{"x":"궁박은 경제적 원인에 기인하는 것을 말하며, 심리적 원인에 기인할 수 없다.","o":"심리적 원인에 기인할 수도 있다.","src":"기출 2022-13 | 기출 2024-10"},{"x":"특별한 사정이 없는 한 경솔·궁박은 본인을 기준으로 판단하고, 무경험은 대리인을 기준으로 판단한다.","o":"경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다.","src":"기출 2022-13 | 기출 2024-15"},{"x":"법률행위가 현저하게 공정성을 잃은 경우, 그 법률행위 당사자의 궁박·경솔·무경험은 추정된다.","o":"추정되지 않는다.","src":"기출 2022-13"},{"x":"불공정한 법률행위에는 무효행위의 전환에 관한 민법 제138조는 적용되지 않는다.","o":"제138조가 적용될 여지가 있다.","src":"기출 2022-13 | 기출 2023-18 | 기출 2025-13"},{"x":"강행규정에 위반한 약정을 한 자가 스스로 그 약정의 무효를 주장하는 것은 특별한 사정이 없는 한 신의성실 원칙에 반하여 허용될 수 없다.","o":"신의칙에 반하지 않는다.","src":"기출 2023-11"},{"x":"특별한 사정이 없는 한 경매에도 불공정한 법률행위에 관한 민법 제104조가 적용된다.","o":"경매에는 제104조가 적용되지 않는다.","src":"기출 2024-10 | 기출 2025-13"},{"x":"무상 증여계약도 불공정한 법률행위가 될 수 있다.","o":"무상행위는 불공정한 법률행위가 될 수 없다.","src":"기출 2025-13"},{"x":"불공정한 법률행위로서 무효인 경우에 선의의 제3자에 대해서는 무효를 주장할 수 없다.","o":"선의의 제3자에게도 무효를 주장할 수 있다.","src":"기출 2025-13"},{"x":"계약이 불공정한 법률행위로서 무효인 경우, 그 계약에 대한 부제소합의는 특별한 사정이 없는 한 유효하다.","o":"부제소합의도 무효이다.","src":"기출 2023-18"},{"x":"매매계약이 약정된 대금의 과다로 인해 불공정한 법률행위에 해당하여 무효인 경우, 무효행위의 전환에 관한 민법 제138조는 적용될 여지가 없다.","o":"제138조가 적용될 여지가 있다.","src":"기출 2023-18 | 기출 2025-13"}]},"#10":{"묶음":[{"머리":"진의 아닌 의사표시(제107조)","줄":[{"t":"의사표시는 표의자가 진의 아님을 알고 한 것이라도 그 효력이 있다(원칙적 유효).","src":"민법 제107조 제1항 본문 | 기출 2025-14"},{"t":"예외: 상대방이 표의자의 진의 아님을 알았거나 이를 알 수 있었을 경우에는 무효이다.","src":"민법 제107조 제1항 단서"},{"t":"이 무효는 선의의 제3자에게 대항하지 못한다.","src":"민법 제107조 제2항"},{"t":"진의: 특정한 내용의 의사표시를 하고자 하는 표의자의 생각이다. 표의자가 진정으로 마음속에서 바라는 사항이 아니다.","src":"기출 2025-14"},{"t":"비진의표시는 표시와 진의의 불일치를 표의자가 알고 있다는 점에서 착오와 구별된다.","src":"기출 2025-14"},{"t":"진의 아님을 알았거나 알 수 있었다는 사실(상대방의 악의·과실)은 무효를 주장하는 사람이 증명하여야 한다.","src":"기출 2025-14 | 보충"},{"t":"표시와 진의의 불일치가 상대방과 합의된 것이면 통정허위표시이다.","src":"기출 2023-16 | 기출 2025-14"}]},{"머리":"통정허위표시(제108조)","줄":[{"t":"상대방과 통정한 허위의 의사표시는 무효로 한다.","src":"민법 제108조 제1항"},{"t":"이 무효는 선의의 제3자에게 대항하지 못한다.","src":"민법 제108조 제2항 | 기출 2021-10"},{"t":"허위표시의 무효는 당사자 사이에서는 누구에게나 주장할 수 있는 절대적 무효이다. 제3자에 대해서는 선의의 제3자에게 대항하지 못한다는 한도에서 상대적이다.","src":"보충"},{"t":"제3자: 허위표시의 당사자와 그 포괄승계인 이외의 자로서 허위표시에 의하여 외형상 형성된 법률관계를 기초로 새로운 법률상 이해관계를 맺은 자.","src":"기출 2022-15 | 보충"},{"t":"제3자의 선의는 추정되며 무과실은 요구되지 않는다. 과실이 있어도 보호된다.","src":"기출 2021-10 | 기출 2024-12 | 보충"},{"t":"제3자에 해당하는 예: 가장매매의 매수인으로부터 그와의 매매계약에 의한 소유권이전청구권 보전을 위한 가등기를 마친 자 / 허위의 선급금 반환채무 부담행위에 기하여 그 채무를 보증하고 이행하여 구상권을 취득한 자 / 가장 저당권자 / 가장 근저당권의 피담보채권을 가압류한 자 / 가장채권의 가압류권자 / 가장 매수인의 전득자.","src":"기출 2021-10 | 기출 2022-15 | 기출 2023-16 | 기출 2024-12"},{"t":"제3자에 해당하지 않는 예: 가장소비대차에서 대주의 계약상 지위를 이전받은 자, 가장양도인의 가장양수인에 대한 권리를 채권자대위권으로 행사하는 채권자, 허위표시의 당사자의 포괄승계인.","src":"기출 2022-15 | 기출 2023-16 | 기출 2024-12 | 보충"},{"t":"가장 매수인(丙)이 악의라도 그로부터 매수한 전득자(丁)가 선의이면 甲은 丁에게 무효를 주장하여 이전등기의 말소를 구할 수 없다.","src":"기출 2021-10 | 보충"},{"t":"파산관재인은 파산채권자 전체의 이익을 대표하는 제3자이다. 파산관재인이 악의라도 파산채권자 중 선의자가 있으면 선의의 제3자로 인정되어 허위표시의 무효로 대항할 수 없다.","src":"기출 2024-12 | 보충"},{"t":"채무자의 법률행위가 통정허위표시인 경우에도 채권자취소권의 대상이 될 수 있다.","src":"기출 2023-16"},{"t":"허위표시에 따른 법률효과를 침해하는 것처럼 보이는 위법행위가 있는 경우에도 그에 따른 손해배상을 청구할 수 없다.","src":"기출 2023-16"},{"t":"허위표시 안에 감추어진 다른 법률행위(은닉행위)는 그 요건을 갖추면 유효하다.","src":"보충"}]}],"함정":[{"x":"만약 X부동산이 乙로부터 丙, 丙으로부터 丁에게 차례로 매도되어 각기 그 명의로 이전 등기까지 된 경우, 허위표시에 대해 丙이 악의이면 丁이 선의이더라도 甲은 丁 명의 이전등기의 말소를 구할 수 있다.","o":"丁이 선의이면 甲은 丁에게 허위표시의 무효로 대항할 수 없어 말소를 구할 수 없다.","src":"민법 제108조 제2항 | 기출 2021-10"},{"x":"자신의 채권을 보전하기 위해 가장양도인의 가장양수인에 대한 권리를 대위행사하는 채권자는 허위표시를 기초로 새로운 법률상의 이해관계를 맺은 제3자에 해당한다.","o":"대위행사 채권자는 제3자에 해당하지 않는다.","src":"기출 2023-16"},{"x":"진의 아님을 알았다는 사실은 의사표시의 유효를 주장하는 사람이 증명해야 한다.","o":"무효를 주장하는 사람이 증명해야 한다.","src":"기출 2025-14"},{"x":"파산관재인 戊가 악의이면 파산채권자 중 일부가 선의라도 乙은 戊에 대하여 대출약정의 무효를 대항할 수 있다.","o":"파산채권자 중 선의자가 있으면 선의의 제3자로 인정되어 대항할 수 없다.","src":"기출 2024-12"}]},"#11":{"묶음":[{"머리":"요건(제109조)","줄":[{"t":"의사표시는 법률행위의 내용의 중요부분에 착오가 있는 때에는 취소할 수 있다.","src":"민법 제109조 제1항 본문 | 기출 2021-11 | 기출 2022-16"},{"t":"그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다.","src":"민법 제109조 제1항 단서"},{"t":"상대방이 표의자의 착오를 알고 이를 이용한 경우에는 표의자에게 중대한 과실이 있어도 취소할 수 있다.","src":"기출 2021-11 | 기출 2024-13 | 보충"},{"t":"취소는 선의의 제3자에게 대항하지 못한다.","src":"민법 제109조 제2항"},{"t":"중요부분의 착오: 표의자가 그 점에 착오가 없었더라면 의사표시를 하지 않았을 것이라고 생각되고, 보통 일반인도 표의자의 처지에 섰더라면 그 의사표시를 하지 않았을 것이라고 생각될 정도로 중요한 부분.","src":"보충"},{"t":"착오로 인하여 표의자가 경제적 불이익을 입은 것이 아니라면 법률행위 내용의 중요부분의 착오라고 할 수 없다.","src":"기출 2022-16 | 기출 2023-17"},{"t":"동기의 착오: 동기가 상대방에게 표시되어 의사표시의 내용이 된 경우 또는 상대방이 유발한 경우 법률행위 내용의 착오가 되어 취소할 수 있다.","src":"보충"},{"t":"표의자가 장래에 있을 어떤 사항의 발생이 미필적임을 알아 그 발생을 예기한 데 지나지 않는 경우, 그 기대가 이루어지지 않은 것을 착오로 볼 수 없다.","src":"기출 2022-16"},{"t":"1심 판결에서 패소한 자가 항소심 판결 선고 전에 패소를 예상하고 한 법률행위는 항소심에서 승소하였더라도 장래 결과에 대한 예측이므로 착오를 이유로 취소할 수 없다.","src":"기출 2021-11"},{"t":"대리인에 의한 계약체결의 경우 특별한 사정이 없는 한 착오의 유무는 대리인을 표준으로 판단한다.","src":"기출 2023-17 | 기출 2024-15 | 민법 제116조 제1항"}]},{"머리":"증명책임·배제·경합","줄":[{"t":"표의자의 중대한 과실 유무의 증명책임은 의사표시를 취소하지 못하게 하려는 상대방에게 있다.","src":"기출 2021-11 | 기출 2022-16 | 기출 2023-17"},{"t":"제109조 제1항은 임의규정이다. 당사자의 합의로 그 적용을 배제할 수 있다.","src":"기출 2022-16 | 기출 2024-13"},{"t":"착오로 인한 취소로 상대방이 손해를 입더라도 착오자는 불법행위로 인한 손해배상책임을 부담하지 않는다(경과실의 경우도 취소로 인한 손해배상책임 없음).","src":"기출 2021-11 | 기출 2024-13"},{"t":"매도인이 매수인의 채무불이행을 이유로 매매계약을 적법하게 해제한 후에도 매수인은 착오를 이유로 매매계약을 취소할 수 있다.","src":"기출 2023-17 | 기출 2024-13"},{"t":"매도인의 하자담보책임이 성립하는 경우에도 매수인은 착오를 이유로 취소할 수 있다(두 규정은 경합).","src":"기출 2024-13 | 보충"},{"t":"취소권은 추인할 수 있는 날부터 3년 내, 법률행위를 한 날부터 10년 내에 행사한다.","src":"민법 제146조"}]}],"함정":[{"x":"1심 판결에서 패소한 자가 항소심 판결 선고 전에 패소를 예상하고 법률행위를 하였으나 이후 항소심에서 승소판결이 선고된 경우 착오를 이유로 그 법률행위를 취소할 수 있다.","o":"장래 결과에 대한 예측이므로 착오로 취소할 수 없다.","src":"기출 2021-11"},{"x":"표의자는 자신에게 중과실이 없음에 대한 주장·증명책임을 부담한다.","o":"중과실의 증명책임은 취소를 막으려는 상대방에게 있다.","src":"기출 2022-16"},{"x":"착오로 인한 의사표시에 있어서 표의자의 중대한 과실 유무에 관한 증명책임은 그 상대방이 아니라 착오자에게 있다.","o":"상대방에게 있다.","src":"기출 2023-17"},{"x":"표의자가 경과실로 인한 착오로 의사표시를 하고 그 착오를 이유로 의사표시를 취소한 경우, 표의자는 그 취소로 인한 손해를 배상할 책임이 있다.","o":"배상책임이 없다.","src":"기출 2024-13"},{"x":"착오로 인한 의사표시의 취소에 관한 민법 제109조 제1항은 당사자의 합의로 그 적용을 배제할 수 없다.","o":"합의로 배제할 수 있다.","src":"기출 2024-13"},{"x":"매도인의 하자담보책임이 성립하는 경우, 매매계약 내용의 중요 부분에 착오가 있더라도 매수인은 착오를 이유로 매매계약을 취소할 수 없다.","o":"하자담보책임이 성립해도 착오를 이유로 취소할 수 있다.","src":"기출 2024-13"},{"x":"상대방이 표의자의 착오를 알고 이를 이용한 경우라도 의사표시의 착오가 표의자의 중대한 과실로 인한 것이라면 표의자는 착오를 이유로 의사표시를 취소할 수 없다.","o":"상대방이 착오를 알고 이용한 경우에는 중대한 과실이 있어도 취소할 수 있다.","src":"기출 2024-13"}]},"#12":{"묶음":[{"머리":"요건과 효과(제110조)","줄":[{"t":"사기나 강박에 의한 의사표시는 취소할 수 있다.","src":"민법 제110조 제1항"},{"t":"상대방 있는 의사표시에 관하여 제3자가 사기나 강박을 행한 경우에는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 취소할 수 있다.","src":"민법 제110조 제2항 | 기출 2021-12"},{"t":"사기·강박에 의한 의사표시의 취소는 선의의 제3자에게 대항하지 못한다. 제3자의 선의는 추정된다.","src":"민법 제110조 제3항 | 기출 2022-14 | 기출 2023-14"},{"t":"상대방 없는 의사표시는 누가 기망·강박을 했는지를 묻지 않고 취소할 수 있다.","src":"기출 2025-15 | 보충"},{"t":"상대방이 기망하였으나 표의자가 기망되지 않고 의사표시를 하였다면 기망을 이유로 취소할 수 없다(인과관계 필요).","src":"기출 2021-12"},{"t":"사기의 고의: 표의자를 기망하여 착오에 빠뜨리고 그 착오로 의사표시를 하게 하려는 고의(이중의 고의). 재산상 손실을 주려는 고의는 필요하지 않다.","src":"기출 2022-14 | 기출 2025-15 | 보충"},{"t":"기망으로 법률행위 내용으로 표시되지 않은 동기에 관하여 착오를 일으킨 경우에도 사기를 이유로 취소할 수 있다.","src":"기출 2022-14 | 기출 2023-17"},{"t":"사기에 의한 의사표시에는 의사와 표시의 불일치가 없다. 의사표시의 동기에 착오가 있는 것에 불과하다.","src":"기출 2023-14 | 기출 2025-15"},{"t":"사기로 인한 부동산 소유권을 취득한 자로부터 새로 취득한 제3자는 특별한 사정이 없는 한 선의로 추정된다.","src":"기출 2023-14"}]},{"머리":"제3자의 범위","줄":[{"t":"상대방의 대리인은 제3자 사기에서의 제3자가 아니다. 상대방과 동일시하여 상대방 자신의 사기로 본다.","src":"기출 2021-12 | 기출 2023-14 | 기출 2025-15 | 기출 2024-15"},{"t":"상대방이 사용자책임을 져야 하는 관계의 피용자는 제3자에 해당한다.","src":"기출 2021-12"},{"t":"제3자의 사기로 계약을 체결한 표의자는 계약을 취소하지 않은 상태에서도 제3자에 대하여 불법행위로 인한 손해배상을 청구할 수 있다.","src":"기출 2021-12 | 기출 2023-14 | 기출 2024-14"}]},{"머리":"기망행위","줄":[{"t":"광고·선전에 다소의 과장이나 허위가 수반되는 것은 일반 상거래의 관행과 신의칙에 비추어 시인될 수 있는 한 기망성이 결여된다.","src":"기출 2022-14 | 기출 2024-14"},{"t":"부작위에 의한 기망: 고지의무가 있는 사람이 알리지 않고 일부러 침묵하면 기망행위가 될 수 있다. 고지의무는 법령·계약뿐 아니라 신의칙·조리상으로도 인정된다.","src":"기출 2022-14 | 기출 2025-15"},{"t":"상대방이 이미 알고 있는 사실에 대해서는 고지의무가 없다.","src":"기출 2024-14 | 보충"},{"t":"교환계약의 당사자가 자기 소유 목적물의 시가를 묵비하는 것은 특별한 사정이 없는 한 기망행위가 되지 않는다.","src":"기출 2023-14"}]},{"머리":"강박","줄":[{"t":"강박: 해악을 고지하여 공포심을 일으키게 하고 그 공포심으로 의사표시를 하게 하는 것. 위법한 강박이어야 한다.","src":"보충"},{"t":"강박에 의한 의사표시의 취소권 행사기간은 제척기간(제146조)이다. 소멸시효가 아니다.","src":"기출 2024-14 | 민법 제146조"},{"t":"소송행위는 강박을 이유로 민법의 취소규정에 의해 취소할 수 없다.","src":"기출 2024-14 | 보충"},{"t":"의사결정의 자유가 완전히 박탈된 상태의 의사표시(절대적 폭력)는 취소가 아니라 무효이다.","src":"보충"}]}],"함정":[{"x":"‘제3자에 의한 사기’로 계약을 체결한 피기망자는 그 계약을 취소하지 않은 상태에서 그 제3자에 대하여 불법행위로 인한 손해배상청구를 할 수 없다.","o":"취소하지 않아도 제3자에 대하여 손해배상을 청구할 수 있다.","src":"기출 2021-12 | 기출 2023-14 | 기출 2024-14"},{"x":"부작위에 의한 기망행위에서 고지의무는 조리상 일반원칙에 의해서는 인정될 수 없다.","o":"신의칙·조리상으로도 고지의무가 인정된다.","src":"기출 2022-14"},{"x":"신의칙상 고지의무를 부담하는 자는 고지의무의 대상이 되는 사실을 이미 알고 있는 자에 대해서도 그 사실을 고지하여야 한다.","o":"이미 알고 있는 자에게는 고지의무가 없다.","src":"기출 2024-14"},{"x":"계약이 제3자의 위법한 사기행위로 체결된 경우, 표의자가 제3자를 상대로 사기로 인한 손해배상을 청구하기 위해서는 그 계약을 취소해야 한다.","o":"취소할 필요가 없다.","src":"기출 2024-14"},{"x":"강박에 의한 의사표시에 대한 취소권의 행사기간은 소멸시효기간이다.","o":"제척기간이다.","src":"기출 2024-14"},{"x":"소송행위가 강박에 의하여 이루어진 경우, 특별한 사정이 없는 한 강박을 이유로 소송행위를 취소할 수 있다.","o":"소송행위는 민법의 취소 규정에 의하여 취소할 수 없다.","src":"기출 2024-14"},{"x":"표의자에게 특정한 의사표시를 하도록 하는 것을 넘어 재산상의 손실을 주려는 기망 행위자의 고의가 있어야 한다.","o":"재산상 손실을 주려는 고의는 필요하지 않다.","src":"기출 2025-15"}]},"#13":{"묶음":[{"머리":"대리의 효력","줄":[{"t":"대리인이 권한 내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 효력이 생긴다. 대리인에 대한 제3자의 의사표시에도 준용한다.","src":"민법 제114조"},{"t":"대리인이 본인을 위한 것임을 표시하지 않은 때 그 의사표시는 자기를 위한 것으로 본다. 그러나 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때에는 본인에게 효력이 있다.","src":"민법 제115조"},{"t":"매매위임장을 제시하고 계약서에 대리인의 성명만 기재한 경우에도 특단의 사정이 없는 한 본인에게 효력이 있다.","src":"기출 2021-13 | 보충"},{"t":"대리행위의 하자: 의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우 그 사실의 유무는 대리인을 표준으로 결정한다.","src":"민법 제116조 제1항"},{"t":"특정한 법률행위를 위임한 경우 대리인이 본인의 지시에 좇아 행위한 때 본인은 자기가 안 사정 또는 과실로 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다.","src":"민법 제116조 제2항 | 기출 2021-13"},{"t":"대리인은 행위능력자임을 요하지 아니한다. 본인은 대리인이 제한능력자라는 이유로 대리행위를 취소할 수 없다.","src":"민법 제117조 | 기출 2021-13 | 기출 2022-11"},{"t":"대리인이 수인인 때에는 각자가 본인을 대리한다. 법률 또는 수권행위에 다른 정한 바가 있으면 그에 따른다.","src":"민법 제119조"},{"t":"자기계약·쌍방대리: 대리인은 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자 쌍방을 대리하지 못한다. 그러나 채무의 이행은 할 수 있다.","src":"민법 제124조"},{"t":"배임적 대리행위: 대리인이 제3자 또는 자기의 이익만을 위하여 대리행위를 하고 상대방이 이를 알았거나 알 수 있었을 때에는 본인에게 효과가 없다(제107조 제1항 단서 유추).","src":"기출 2021-13 | 보충"},{"t":"하나의 물건에 대해 본인과 대리인이 각각 계약을 체결한 경우, 대리인이 체결한 계약도 유효하다.","src":"기출 2021-13 | 보충"}]},{"머리":"대리권","줄":[{"t":"수권행위는 묵시적인 의사표시로 할 수 있고, 사실상의 용태에 의하여 대리권의 수여가 추단될 수 있다.","src":"기출 2021-14 | 기출 2022-11"},{"t":"임의대리권의 범위는 원칙적으로 수권행위에 의하여 정해진다.","src":"기출 2022-9"},{"t":"권한을 정하지 아니한 대리인은 ① 보존행위 ② 대리의 목적인 물건이나 권리의 성질을 변하지 아니하는 범위에서 이용 또는 개량하는 행위만 할 수 있다.","src":"민법 제118조 | 기출 2021-14 | 기출 2022-11"},{"t":"대리권은 그 권한에 부수하여 필요한 한도에서 상대방의 의사표시를 수령하는 수령대리권을 포함한다.","src":"기출 2021-14 | 기출 2022-9"},{"t":"매매계약 체결 대리권을 수여받은 자는 특별한 사정이 없는 한 중도금·잔금을 수령할 권한이 있다.","src":"기출 2022-9 | 보충"},{"t":"매매계약의 체결과 이행에 대하여 포괄적인 대리권을 수여받은 자는 특별한 사정이 없는 한 약정된 매매대금의 지급기일을 연기해 줄 권한이 있다.","src":"기출 2022-9 | 보충"},{"t":"부동산을 매수할 권한을 수여받은 자는 원칙적으로 그 부동산을 처분할 권한이 없다.","src":"기출 2022-9"},{"t":"대리권의 소멸사유: ① 본인의 사망 ② 대리인의 사망, 성년후견의 개시 또는 파산.","src":"민법 제127조 | 기출 2021-14"},{"t":"임의대리의 종료: 대리권 소멸사유 외에 원인된 법률관계의 종료에 의하여 소멸한다. 법률관계의 종료 전에 본인이 수권행위를 철회한 경우에도 같다.","src":"민법 제128조 | 기출 2021-14 | 기출 2022-11"},{"t":"대리인에 대한 성년후견의 개시는 대리권의 소멸사유이다. 피한정후견인·피특정후견인에 대한 후견 개시는 소멸사유가 아니다.","src":"민법 제127조 제2호 | 기출 2021-14"}]},{"머리":"복대리","줄":[{"t":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","src":"민법 제120조 | 기출 2023-20"},{"t":"임의대리인이 복대리인을 선임한 때에는 본인에 대하여 그 선임·감독에 관한 책임이 있다.","src":"민법 제121조 제1항 | 기출 2021-15"},{"t":"본인의 지명에 의하여 선임한 경우에는 그 부적임 또는 불성실함을 알고 본인에게 대한 통지나 그 해임을 태만한 때가 아니면 책임이 없다.","src":"민법 제121조 제2항"},{"t":"법정대리인은 언제나 자기 책임으로 복대리인을 선임할 수 있다(복임권). 부득이한 사유로 선임한 때에는 제121조 제1항의 책임(선임·감독상 책임)만 진다.","src":"민법 제122조 | 기출 2021-15 | 기출 2023-20"},{"t":"복대리인은 본인의 대리인이다. 대리인의 대리인이 아니다. 복대리인은 법정대리인이 아니라 임의대리인이다.","src":"기출 2021-15 | 기출 2022-11 | 기출 2023-20"},{"t":"복대리인은 그 권한 내에서 본인을 대리하며, 본인이나 제3자에 대하여 대리인과 동일한 권리의무가 있다.","src":"민법 제123조"},{"t":"복대리인을 선임해도 대리인의 대리권은 소멸하지 않는다.","src":"기출 2023-20"},{"t":"대리인의 대리권이 소멸하면(사망·파산 등) 복대리권도 소멸한다.","src":"기출 2021-15 | 기출 2023-20"},{"t":"복대리인은 수령한 법률행위의 목적물을 대리인에게 인도할 의무가 있다.","src":"기출 2021-15"}]}],"함정":[{"x":"매매위임장을 제시하고 매매계약을 체결하면서 계약서에 대리인의 성명만 기재하는 경우, 특단의 사정이 없는 한 그 계약은 본인에게 효력이 없다.","o":"특단의 사정이 없는 한 본인에게 효력이 있다.","src":"기출 2021-13"},{"x":"특정한 법률행위를 위임한 경우에 대리인이 본인의 지시에 좇아 그 행위를 한 때에는 본인은 자기가 안 사정에 관하여 대리인의 부지(不知)를 주장할 수 있다.","o":"주장하지 못한다(제116조 제2항).","src":"민법 제116조 제2항 | 기출 2021-13"},{"x":"하나의 물건에 대해 본인과 대리인이 각각 계약을 체결한 경우, 대리인이 체결한 계약은 무효이다.","o":"대리인이 체결한 계약도 유효하다.","src":"기출 2021-13"},{"x":"본인은 임의대리인이 제한능력자라는 이유로 대리행위를 취소할 수 있다.","o":"대리인은 행위능력자임을 요하지 않으므로 취소할 수 없다.","src":"민법 제117조 | 기출 2021-13"},{"x":"권한을 정하지 아니한 대리인은 대리의 목적물에 대해 모든 개량행위를 할 수 있다.","o":"성질을 변하지 아니하는 범위에서 이용·개량행위만 할 수 있다.","src":"민법 제118조 제2호 | 기출 2021-14"},{"x":"매도인으로부터 매매계약의 체결과 이행에 대해 포괄적인 대리권을 수여받은 자는 특별한 사정이 없는 한 약정된 매매대금의 지급기일을 연기해 줄 권한이 없다.","o":"지급기일을 연기해 줄 권한이 있다.","src":"기출 2022-9"},{"x":"수권행위에서 권한을 정하지 아니한 대리인은 보존행위만을 할 수 있다.","o":"보존행위와 성질을 변하지 않는 범위의 이용·개량행위를 할 수 있다.","src":"민법 제118조 | 기출 2022-11"},{"x":"복대리인은 대리인의 대리인이다.","o":"복대리인은 본인의 대리인이다.","src":"기출 2023-20"},{"x":"대리인이 파산하여도 복대리권은 소멸하지 않는다.","o":"대리인이 파산하면 대리권이 소멸하고 복대리권도 소멸한다.","src":"민법 제127조 | 기출 2023-20"},{"x":"임의대리인은 본인의 승낙이 있는 때에 한하여 복임권을 갖는다.","o":"본인의 승낙이 있거나 부득이한 사유가 있는 때에 복대리인을 선임할 수 있다.","src":"민법 제120조 | 기출 2023-20"},{"x":"복대리인이 선임되면 특별한 사정이 없는 한 대리인의 대리권은 소멸한다.","o":"대리인의 대리권은 소멸하지 않는다.","src":"기출 2023-20"},{"x":"매매계약 내용의 중요부분에 관하여 乙의 착오가 있는 경우, 甲에게는 착오가 없더라도 乙은 자신의 착오를 이유로 매매계약을 취소할 수 있다.","o":"대리인에 의한 계약은 착오 유무를 대리인을 표준으로 판단하므로 대리인에게 착오가 없으면 취소할 수 없다.","src":"민법 제116조 제1항 | 기출 2024-15"}]},"#14":{"묶음":[{"머리":"표현대리 3유형","줄":[{"t":"대리권수여의 표시에 의한 표현대리: 제3자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권의 범위 내에서 책임이 있다. 제3자가 대리권 없음을 알았거나 알 수 있었을 때에는 책임이 없다.","src":"민법 제125조 | 기출 2025-16"},{"t":"권한을 넘은 표현대리: 대리인이 그 권한 외의 법률행위를 한 경우 제3자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때 본인은 책임이 있다.","src":"민법 제126조"},{"t":"대리권 소멸 후의 표현대리: 대리권의 소멸은 선의의 제3자에게 대항하지 못한다. 그러나 제3자가 과실로 그 사실을 알지 못한 때에는 그러하지 아니하다.","src":"민법 제129조"},{"t":"제125조·제129조는 선의·무과실이, 제126조는 정당한 이유(상대방의 선의·무과실)가 필요하다.","src":"민법 제125조 | 민법 제126조 | 민법 제129조 | 기출 2025-16"},{"t":"권한을 넘은 표현대리에서 기본대리권은 권한 외 행위와 동종의 것일 필요가 없다.","src":"기출 2021-17"},{"t":"법정대리권도 권한을 넘은 표현대리의 기본대리권이 된다. 제126조는 법정대리에도 적용된다.","src":"기출 2024-16 | 기출 2025-16"},{"t":"복임권이 없는 대리인이 선임한 복대리인의 대리권도 기본대리권이 될 수 있다.","src":"기출 2021-17 | 기출 2024-16"},{"t":"대리권 소멸 후의 표현대리가 인정되는 경우 그 표현대리의 권한을 넘은 대리행위가 있을 때에는 권한을 넘은 표현대리가 성립할 수 있다.","src":"기출 2024-16"},{"t":"정당한 이유의 유무는 대리행위 당시를 기준으로 판단한다.","src":"기출 2021-17 | 기출 2024-16"},{"t":"제126조의 제3자는 표현대리행위의 직접 상대방만을 뜻한다. 전득자는 포함되지 않는다.","src":"기출 2021-17 | 보충"},{"t":"대리행위의 표시를 하지 않고 성명을 모용하여 자기가 본인인 것처럼 기망하여 본인 명의로 직접 법률행위를 한 경우 특별한 사정이 없는 한 권한을 넘은 표현대리는 성립하지 않는다.","src":"기출 2021-17 | 기출 2024-16"},{"t":"처음부터 아무 대리권도 없었던 사람의 대리행위에는 대리권 소멸 후의 표현대리를 유추적용할 수 없다.","src":"기출 2025-16 | 보충"},{"t":"대리행위가 강행법규 위반으로 무효이면 표현대리 법리가 적용되지 않는다.","src":"기출 2021-19 | 기출 2025-16"},{"t":"표현대리가 성립하면 상대방에게 과실이 있어도 과실상계의 법리를 유추적용하여 본인의 책임을 경감할 수 없다.","src":"기출 2021-19 | 기출 2025-16"},{"t":"유권대리 주장 속에는 표현대리의 주장이 포함되어 있지 않다. 표현대리는 별도로 주장하여야 한다.","src":"기출 2021-19 | 보충"}]},{"머리":"무권대리","줄":[{"t":"대리권 없는 자가 타인의 대리인으로 한 계약은 본인이 추인하지 아니하면 본인에 대하여 효력이 없다(유동적 무효).","src":"민법 제130조"},{"t":"상대방의 최고권: 상대방은 상당한 기간을 정하여 본인에게 추인 여부의 확답을 최고할 수 있다. 본인이 그 기간 내에 확답을 발하지 아니하면 추인을 거절한 것으로 본다.","src":"민법 제131조 | 기출 2023-21"},{"t":"최고권은 계약 당시 무권대리임을 알았던 상대방도 행사할 수 있다.","src":"민법 제131조 | 기출 2023-21"},{"t":"추인과 거절의 상대방: 추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 그 상대방에게 대항하지 못한다. 상대방이 그 사실을 안 때에는 그러하지 아니하다. 무권대리인에게 한 추인도 상대방이 알면 효력이 있다.","src":"민법 제132조 | 기출 2021-18 | 기출 2022-12"},{"t":"추인의 효력: 다른 의사표시가 없으면 계약 시에 소급하여 효력이 생긴다. 제3자의 권리를 해하지 못한다.","src":"민법 제133조 | 기출 2023-18"},{"t":"추인은 무권대리행위가 있음을 알고 하여야 한다. 무권대리인의 동의는 필요 없다.","src":"기출 2022-12 | 보충"},{"t":"추인은 묵시적으로 할 수 있다. 다만 무권대리행위가 범죄가 되는 경우 장기간 형사고소를 하지 않았다는 사실만으로 묵시적 추인이 인정되지 않는다.","src":"기출 2021-18 | 기출 2022-12"},{"t":"일부 추인이나 내용을 변경한 추인은 상대방의 동의를 얻어야 유효하다.","src":"기출 2021-18 | 기출 2022-12 | 기출 2023-21"},{"t":"상대방의 철회권: 계약은 본인의 추인이 있을 때까지 상대방이 본인이나 그 대리인에 대하여 철회할 수 있다. 계약 당시 상대방이 대리권 없음을 안 때에는 철회할 수 없다.","src":"민법 제134조 | 기출 2021-19 | 기출 2023-21"},{"t":"본인이 추인을 거절하면 무권대리행위는 확정적으로 무효가 되므로 그 후에는 상대방의 철회권이 문제되지 않는다.","src":"기출 2021-18 | 보충"},{"t":"무권대리인의 책임: 대리권을 증명하지 못하고 본인의 추인도 받지 못한 경우 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다.","src":"민법 제135조 제1항"},{"t":"무권대리인의 책임은 대리권 흠결에 관한 무과실책임이다(대리인의 과실이 필요 없다).","src":"기출 2021-18 | 보충"},{"t":"무권대리인 책임이 배제되는 경우: 상대방이 대리권 없음을 알았거나 알 수 있었을 때, 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때.","src":"민법 제135조 제2항 | 기출 2021-19 | 기출 2023-21"},{"t":"단독행위의 무권대리: 행위 당시 상대방이 대리인이라 칭하는 자의 대리권 없는 행위에 동의하거나 그 대리권을 다투지 아니한 때에 한하여 제130조~제135조를 준용한다. 대리권 없는 자에 대하여 그 동의를 얻어 단독행위를 한 때에도 같다.","src":"민법 제136조"},{"t":"무권대리인이 본인을 단독상속한 경우 본인의 지위에서 추인을 거절하는 것은 신의칙에 반하여 허용되지 않는다.","src":"기출 2022-2 | 기출 2023-21 | 기출 2025-2"}]}],"함정":[{"x":"권한을 넘은 표현대리에 관한 규정에서의 제3자에는 당해 표현대리행위의 직접 상대방이 된 자 외에 전득자도 포함된다.","o":"직접 상대방만 해당한다. 전득자는 포함되지 않는다.","src":"기출 2021-17"},{"x":"범죄가 되는 무권대리행위에 대하여 장기간 형사고소를 하지 아니하였다는 사실만으로 묵시적인 추인이 있었다고 볼 수 있다.","o":"이것만으로 묵시적 추인으로 볼 수 없다.","src":"기출 2021-18 | 기출 2022-12"},{"x":"본인이 추인을 거절하더라도 상대방은 철회권을 행사할 수 있다.","o":"추인 거절로 무효가 확정되므로 철회권이 문제되지 않는다. 철회권은 추인이 있을 때까지 행사할 수 있는 권리이다.","src":"민법 제134조 | 기출 2021-18"},{"x":"본인이 무권대리인에게 한 추인의 의사표시는 항상 효력이 없다.","o":"상대방이 그 사실을 안 때에는 무권대리인에게 한 추인도 효력이 있다.","src":"민법 제132조 | 기출 2021-18"},{"x":"무권대리인의 계약상대방에 대한 책임(민법 제135조 제1항)은 대리권의 흠결에 관하여 대리인에게 과실이 있어야 인정된다.","o":"무과실책임이다.","src":"기출 2021-18"},{"x":"제한능력자인 무권대리인은 민법 제135조 제1항에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다.","o":"제한능력자인 무권대리인은 책임이 없다.","src":"민법 제135조 제2항 | 기출 2021-19"},{"x":"추인은 무권대리인의 동의가 있어야 유효하다.","o":"무권대리인의 동의는 필요하지 않다.","src":"기출 2022-12"},{"x":"추인은 무권대리인이 아닌 무권대리행위의 상대방에게 하여야 한다.","o":"상대방 또는 무권대리인에게 할 수 있다. 무권대리인에게 한 추인은 상대방이 그 사실을 알기 전에는 상대방에게 대항하지 못한다.","src":"민법 제132조 | 기출 2022-12"},{"x":"무권대리행위가 범죄가 되는 경우, 본인이 그 사실을 알고 장기간 형사고소를 하지 않았다면 묵시적 추인이 인정된다.","o":"그것만으로는 묵시적 추인이 인정되지 않는다.","src":"기출 2022-12"},{"x":"무권대리행위의 일부에 대한 추인은 상대방의 동의가 없더라도 유효하다.","o":"일부 추인은 상대방의 동의가 있어야 유효하다.","src":"기출 2022-12"},{"x":"乙이 대리권을 증명하지 못하고 甲의 추인도 받지 못한 경우, 丙은 계약 체결 당시 乙이 무권대리인임을 알았더라도 乙에게 계약의 이행이나 손해배상을 청구할 수 있다.","o":"상대방이 알았거나 알 수 있었을 때에는 무권대리인의 책임이 없다.","src":"민법 제135조 제2항 | 기출 2023-21"},{"x":"복대리인 선임권이 없는 대리인에 의하여 선임된 복대리인의 권한은 기본대리권이 될 수 없다.","o":"복임권이 없는 대리인이 선임한 복대리인의 권한도 기본대리권이 될 수 있다.","src":"기출 2024-16"},{"x":"대리행위가 강행법규 위반으로 무효이더라도 표현대리 법리가 적용된다.","o":"표현대리 법리가 적용되지 않는다.","src":"기출 2025-16"},{"x":"처음부터 아무 대리권도 없었던 사람의 대리행위에 대하여 대리권 소멸 후의 표현대리를 유추 적용할 수 있다.","o":"유추적용할 수 없다.","src":"기출 2025-16"},{"x":"대리권 수여의 표시로 인한 표현대리에서 대리권 존재에 대한 상대방의 선의 및 무과실은 요건이 아니다.","o":"상대방이 대리권 없음을 알았거나 알 수 있었을 때에는 책임이 없다. 선의·무과실이 필요하다.","src":"민법 제125조 | 기출 2025-16"},{"x":"표현대리의 성립으로 본인이 이행책임을 질 때 상대방의 과실이 있는 경우에는 과실상계의 법리에 따라 본인의 책임이 경감된다.","o":"과실상계의 법리를 유추적용하여 본인의 책임을 경감할 수 없다.","src":"기출 2025-16 | 기출 2021-19"}]},"#15":{"묶음":[{"머리":"무효","줄":[{"t":"무효: 법률행위의 효력이 처음부터 발생하지 않는 것. 누구든지 무효를 주장할 수 있다. 취소권자 제한(제140조)은 무효에 적용되지 않는다.","src":"보충 | 기출 2022-19"},{"t":"일부무효: 법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 그러나 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다.","src":"민법 제137조 | 기출 2021-20 | 기출 2025-17"},{"t":"무효행위의 전환: 무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다.","src":"민법 제138조 | 기출 2025-17"},{"t":"무효행위의 추인: 무효인 법률행위는 추인하여도 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다(소급효 없음).","src":"민법 제139조 | 기출 2021-20 | 기출 2025-17"},{"t":"무효행위의 추인은 묵시적으로 할 수 있다.","src":"기출 2024-17"},{"t":"무효행위 추인의 기간 제한: 취소권의 3년·10년 제한(제146조)은 무효행위의 추인에 적용되지 않는다.","src":"민법 제146조 | 기출 2022-19"},{"t":"추인으로 유효하게 될 수 없는 무효: 불공정한 법률행위, 강행규정 위반으로 확정적 무효인 행위, 반사회질서 행위.","src":"기출 2021-20 | 기출 2022-13 | 기출 2023-11 | 보충"},{"t":"반사회질서의 법률행위로서 무효인 경우 선의의 제3자에게도 대항할 수 있다.","src":"기출 2024-17"},{"t":"진의 아닌 의사표시는 원칙적으로 유효이다(예외적으로 상대방 악의·과실 시 무효).","src":"민법 제107조 | 기출 2022-19"},{"t":"법률행위가 무효와 취소사유를 모두 포함하고 있는 경우, 당사자는 취소권이 있다면 무효에 따른 효과를 제거하기 위해 이미 무효인 법률행위를 취소할 수 있다(이중효과).","src":"기출 2022-19 | 보충"},{"t":"타인의 권리를 목적으로 하는 매매계약은 유효하다. 매도인은 권리를 취득하여 이전할 의무가 있다(제569조).","src":"기출 2022-19 | 민법 제569조"},{"t":"무권리자가 타인의 권리를 처분하는 계약을 한 경우 권리자가 추인하면 그 계약의 효과는 원칙적으로 계약체결 시로 소급하여 권리자에게 귀속한다.","src":"기출 2023-18 | 기출 2025-17"},{"t":"토지거래허가구역 내 토지의 매매: 허가 전에는 유동적 무효이다. 허가를 받으면 소급하여 유효가 되고, 불허가 확정이나 허가를 배제·잠탈하는 내용의 계약은 확정적 무효이다.","src":"기출 2024-17 | 기출 2025-17 | 보충"},{"t":"의사무능력을 이유로 무효인 경우 의사무능력자는 받은 이익이 현존하는 한도에서 반환한다.","src":"기출 2021-20 | 기출 2024-2"}]},{"머리":"취소","줄":[{"t":"취소권자: 제한능력자, 착오로 인하거나 사기·강박에 의하여 의사표시를 한 자, 그의 대리인 또는 승계인만이 취소할 수 있다.","src":"민법 제140조"},{"t":"제한능력자도 단독으로 취소권을 행사할 수 있다.","src":"기출 2021-21"},{"t":"취소의 효과: 취소된 법률행위는 처음부터 무효인 것으로 본다. 다만 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환할 책임이 있다(선의·악의 불문).","src":"민법 제141조 | 기출 2024-18"},{"t":"취소의 상대방: 취소할 수 있는 법률행위의 상대방이 확정한 경우 취소는 그 상대방에 대한 의사표시로 하여야 한다.","src":"민법 제142조 | 기출 2024-17"},{"t":"상대방이 취소할 수 있는 행위로 취득한 권리를 제3자에게 양도한 경우에도 취소의 의사표시는 원래의 상대방에게 한다. 양수인이 상대방이 되는 것이 아니다.","src":"민법 제142조 | 기출 2023-18 | 보충"},{"t":"취소된 법률행위도 무효행위의 추인 요건(제139조)으로 추인할 수 있다.","src":"기출 2021-21 | 보충"},{"t":"근로계약이 취소된 경우 이미 제공된 노무를 기초로 형성된 취소 이전의 법률관계는 소급하여 효력을 잃지 않는다.","src":"기출 2021-21"},{"t":"계약이 해제된 후에도 해제의 상대방은 해제로 인한 불이익을 면하기 위하여 착오 등을 이유로 취소권을 행사하여 계약 전체를 무효로 돌릴 수 있다.","src":"기출 2021-21"}]},{"머리":"추인과 법정추인","줄":[{"t":"추인: 취소할 수 있는 법률행위는 제140조의 취소권자가 추인할 수 있고, 추인 후에는 취소하지 못한다.","src":"민법 제143조 제1항"},{"t":"추인은 취소의 원인이 소멸된 후에 하여야만 효력이 있다. 법정대리인 또는 후견인이 추인하는 경우에는 이 제한이 없다.","src":"민법 제144조 | 기출 2024-18"},{"t":"법정추인 요건: ① 추인할 수 있는 후에 ② 아래 사유가 있고 ③ 이의를 보류하지 아니하였을 것.","src":"민법 제145조 | 기출 2021-21"},{"t":"법정추인 사유 6가지: ① 전부나 일부의 이행 ② 이행의 청구 ③ 경개 ④ 담보의 제공 ⑤ 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 ⑥ 강제집행.","src":"민법 제145조 | 기출 2022-20 | 기출 2025-19"},{"t":"법정추인이 되는 이행의 청구는 취소권자가 상대방에게 하는 청구이다. 취소권자의 상대방이 취소권자에게 이행을 청구하는 것은 법정추인이 아니다.","src":"기출 2022-20 | 기출 2023-18 | 기출 2025-19 | 보충"},{"t":"취소권자의 상대방이 취소할 수 있는 행위로 취득한 권리를 제3자에게 양도하는 것은 법정추인 사유가 아니다. 사유가 되는 것은 취소권자가 취득한 권리의 양도이다.","src":"기출 2022-20 | 보충"},{"t":"취소권자가 추인할 수 있은 후에 이의를 보류한 상태에서 취소할 수 있는 계약을 이행한 때에는 법정추인이 되지 않는다.","src":"민법 제145조 단서 | 기출 2021-21"}]},{"머리":"취소권의 소멸(제146조)","줄":[{"t":"취소권은 추인할 수 있는 날부터 3년 내에, 법률행위를 한 날부터 10년 내에 행사하여야 한다.","src":"민법 제146조 | 기출 2024-18 | 기출 2025-18"},{"t":"두 기간은 제척기간이다. 어느 하나라도 먼저 지나면 취소권은 소멸한다.","src":"민법 제146조 | 기출 2025-18 | 보충"},{"t":"추인할 수 있는 날: 취소 원인이 종료되어 취소권행사에 관한 장애가 없어지고 취소권자가 추인할 수도 취소할 수도 있는 상태가 된 때.","src":"기출 2025-18"},{"t":"미성년자가 성년에 이른 날부터 3년, 법정대리인이 미성년자의 매매계약을 안 날부터 3년, 그 계약을 한 날부터 10년 중 어느 것이든 먼저 지나면 취소권을 행사할 수 없다.","src":"기출 2025-18 | 보충"},{"t":"취소권은 재판상이든 재판 외이든 제146조의 기간 내에 행사하면 된다.","src":"기출 2025-18"}]}],"함정":[{"x":"법률행위의 일부분이 무효이면 그 일부분만 무효로 되는 것이 원칙이다.","o":"일부분이 무효이면 그 전부를 무효로 하는 것이 원칙이다. 나머지만으로도 했으리라고 인정되면 나머지는 유효이다.","src":"민법 제137조 | 기출 2021-20"},{"x":"의사무능력을 이유로 법률행위가 무효인 경우 의사무능력자는 이익의 현존여부를 불문하고 받은 이익 전부를 반환하여야 한다.","o":"받은 이익이 현존하는 한도에서 반환한다.","src":"기출 2021-20"},{"x":"무효인 법률행위에 대해 당사자가 무효임을 알고 추인하면 그 법률행위는 소급하여 유효하게 되는 것이 원칙이다.","o":"새로운 법률행위로 보며 소급효가 없다.","src":"민법 제139조 | 기출 2021-20"},{"x":"반사회적 법률행위로서 무효인 경우 그 무효로 선의의 제3자에게 대항할 수 없다.","o":"선의의 제3자에게도 대항할 수 있다.","src":"기출 2021-20"},{"x":"법률행위의 취소로 무효가 된 그 법률행위는 무효행위의 추인의 법리에 따라 추인할 수 없다.","o":"무효행위의 추인 요건에 따라 추인할 수 있다.","src":"기출 2021-21"},{"x":"진의 아닌 의사표시는 원칙적으로 무효이다.","o":"원칙적으로 유효이다.","src":"민법 제107조 | 기출 2022-19"},{"x":"법률행위가 무효와 취소사유를 모두 포함하고 있는 경우, 당사자는 취소권이 있더라도 무효에 따른 효과를 제거하기 위해 이미 무효인 법률행위를 취소할 수 없다.","o":"이중효과가 인정되어 취소할 수 있다.","src":"기출 2022-19"},{"x":"법률행위의 무효는 제한능력자, 착오나 사기·강박에 의하여 의사표시를 한 자, 그의 대리인 또는 승계인 이외에는 주장할 수 없다.","o":"무효는 누구든지 주장할 수 있다. 위 제한은 취소권자에 관한 것이다.","src":"민법 제140조 | 기출 2022-19"},{"x":"무효인 법률행위는 추인할 수 있는 날로부터 3년, 법률행위를 한 날로부터 10년 이후에는 추인할 수 없다.","o":"3년·10년 제한은 취소권(제146조)에 관한 것이다. 무효행위의 추인에는 이 제한이 없다.","src":"민법 제146조 | 기출 2022-19"},{"x":"취소할 수 있는 법률행위에서 취소권자의 상대방이 이행을 청구하는 경우에는 법정추인이 된다.","o":"취소권자가 상대방에게 하는 이행의 청구가 법정추인 사유이다. 상대방의 청구는 사유가 아니다.","src":"민법 제145조 제2호 | 기출 2023-18"},{"x":"취소할 수 있는 법률행위의 상대방이 그 법률행위로 취득한 권리를 타인에게 임의로 양도한 경우, 특별한 사정이 없는 한 그 취소의 의사표시는 그 양수인을 상대방으로 하여야 한다.","o":"취소의 의사표시는 원래의 상대방에게 하여야 한다.","src":"민법 제142조 | 기출 2023-18"},{"x":"토지거래계약 허가구역 내 토지에 대하여 처음부터 허가를 잠탈하는 내용의 매매계약이 체결된 경우, 그 계약은 유동적 무효이다.","o":"확정적 무효이다.","src":"기출 2024-17 | 기출 2025-17"},{"x":"甲의 법정대리인이 취소할 수 있는 법률행위를 추인하는 경우, 그 추인은 취소의 원인이 소멸된 후에 하여야만 효력이 있다.","o":"법정대리인이 추인하는 경우에는 취소 원인이 소멸하기 전에도 할 수 있다.","src":"민법 제144조 제2항 | 기출 2024-18"},{"x":"민법 제146조의 취소권 소멸 규정은 제척기간이 아니라 소멸시효기간에 관한 것이다.","o":"제척기간이다.","src":"기출 2025-18"}]},"#16":{"묶음":[{"머리":"조건","줄":[{"t":"조건: 법률행위 효력의 발생 또는 소멸을 장래의 불확실한 사실의 성부에 의존하게 하는 부관.","src":"보충"},{"t":"조건의사와 그 표시가 필요하다. 조건의사가 있어도 외부에 표시되지 않으면 원칙적으로 법률행위의 동기에 불과하다.","src":"기출 2023-19"},{"t":"정지조건 있는 법률행위는 조건이 성취한 때로부터 효력이 생긴다.","src":"민법 제147조 제1항 | 기출 2024-20"},{"t":"해제조건 있는 법률행위는 조건이 성취한 때로부터 효력을 잃는다.","src":"민법 제147조 제2항 | 기출 2025-20"},{"t":"당사자가 조건성취의 효력을 그 성취 전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다.","src":"민법 제147조 제3항"},{"t":"조건부 권리의 침해 금지: 조건 있는 법률행위의 당사자는 조건의 성부가 미정한 동안에 조건의 성취로 인하여 생길 상대방의 이익을 해하지 못한다.","src":"민법 제148조 | 기출 2024-19"},{"t":"조건의 성취가 미정한 권리의무는 일반규정에 의하여 처분, 상속, 보존 또는 담보로 할 수 있다.","src":"민법 제149조 | 기출 2024-20 | 기출 2025-20"},{"t":"조건성취 방해: 조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때 상대방은 그 조건이 성취한 것으로 주장할 수 있다.","src":"민법 제150조 제1항 | 기출 2023-19"},{"t":"조건성취 야기: 조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때 상대방은 그 조건이 성취하지 아니한 것으로 주장할 수 있다.","src":"민법 제150조 제2항 | 기출 2025-2"},{"t":"불법조건: 조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위 전부를 무효로 한다(조건만이 무효가 아니다).","src":"민법 제151조 제1항 | 기출 2022-18 | 기출 2024-19 | 기출 2025-20"},{"t":"기성조건: 법률행위 당시 이미 성취한 조건이 정지조건이면 조건 없는 법률행위, 해제조건이면 그 법률행위는 무효.","src":"민법 제151조 제2항"},{"t":"불능조건: 법률행위 당시 이미 성취할 수 없는 조건이 해제조건이면 조건 없는 법률행위, 정지조건이면 그 법률행위는 무효.","src":"민법 제151조 제3항 | 기출 2022-18 | 기출 2024-20 | 기출 2025-20"},{"t":"조건을 붙일 수 없는 행위: 상계(제493조 제1항), 취소·추인·해제·해지 등 단독행위로서 상대방의 지위를 불안하게 하는 행위, 혼인·입양 등 신분행위.","src":"민법 제493조 제1항 | 기출 2022-18 | 보충"},{"t":"2024년 4월에 ‘2024년 제12회 행정사 시험에 응시하여 최종 합격하면 자동차를 사준다’는 법률행위는 정지조건부 법률행위이다.","src":"기출 2024-19"}]},{"머리":"기한","줄":[{"t":"시기 있는 법률행위는 기한이 도래한 때로부터 효력이 생긴다. 종기 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다.","src":"민법 제152조 | 기출 2022-18 | 기출 2024-20 | 기출 2025-10"},{"t":"기한 도래의 효과는 당사자의 특약으로도 소급하게 할 수 없다(조건과 달리 소급효 없음).","src":"민법 제152조 | 기출 2023-19 | 보충"},{"t":"기한은 채무자의 이익을 위한 것으로 추정한다.","src":"민법 제153조 제1항 | 기출 2022-18 | 기출 2024-19 | 기출 2025-20"},{"t":"기한의 이익은 이를 포기할 수 있다. 그러나 상대방의 이익을 해하지 못한다. 상대방의 손해를 배상하고 포기할 수 있다.","src":"민법 제153조 제2항 | 기출 2024-20"},{"t":"기한부 법률행위에는 제148조·제149조를 준용한다.","src":"민법 제154조"},{"t":"기한의 이익의 상실(제388조): 채무자가 담보를 손상·감소 또는 멸실하게 한 때, 채무자가 담보제공의무를 이행하지 아니한 때 기한의 이익을 주장하지 못한다.","src":"민법 제388조 | 기출 2024-19"},{"t":"기한이익 상실 특약은 특별한 사정이 없는 한 청구 시 상실하는 형성권적 기한이익 상실 특약으로 추정한다(정지조건부 특약으로 추정하지 않는다).","src":"기출 2023-19 | 기출 2025-24 | 보충"},{"t":"불확정한 사실이 발생한 때를 이행기한으로 정한 경우 그 사실의 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다.","src":"기출 2023-19 | 보충"}]}],"함정":[{"x":"상계의 의사표시에는 원칙적으로 조건을 붙일 수 있다.","o":"상계의 의사표시에는 조건을 붙이지 못한다.","src":"민법 제493조 제1항 | 기출 2022-18"},{"x":"조건부 법률행위에서 조건의 내용자체가 불법적이어서 무효인 경우, 원칙적으로 그 조건만이 무효이고 나머지 법률행위는 유효이다.","o":"불법조건이 붙은 법률행위는 전부 무효이다.","src":"민법 제151조 제1항 | 기출 2022-18"},{"x":"해제조건부 법률행위의 조건이 불능조건인 경우, 그 법률행위는 무효이다.","o":"해제조건이 불능조건이면 조건 없는 법률행위가 된다.","src":"민법 제151조 제3항 | 기출 2022-18"},{"x":"시기(始期) 있는 법률행위는 기한이 도래한 때로부터 그 효력을 잃는다.","o":"시기 있는 법률행위는 기한 도래 시부터 효력이 생긴다. 효력을 잃는 것은 종기이다.","src":"민법 제152조 | 기출 2022-18"},{"x":"기한이익 상실의 특약은 특별한 사정이 없는 한 정지조건부 기한이익 상실의 특약으로 추정한다.","o":"형성권적 기한이익 상실 특약으로 추정한다.","src":"기출 2023-19"},{"x":"당사자가 불확정한 사실이 발생한 때를 이행기한으로 정한 경우, 그 사실의 발생이 불가능하게 된 때에는 기한의 도래로 볼 수 없다.","o":"사실의 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다.","src":"기출 2023-19"},{"x":"조건성취로 불이익을 받을 자가 과실로 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 조건이 성취된 것으로 주장할 수 없다.","o":"신의성실에 반하여 방해한 때에는 상대방이 조건이 성취된 것으로 주장할 수 있다.","src":"민법 제150조 제1항 | 기출 2023-19"},{"x":"기한부 법률행위의 당사자가 기한도래의 효력을 그 도래 전으로 소급하게 할 의사를 표시한 때에는 그 의사에 의한다.","o":"기한 도래의 효력은 소급하게 할 수 없다. 소급 특약은 조건에서만 인정된다.","src":"민법 제147조 제3항 | 기출 2023-19"},{"x":"불법조건이 붙은 법률행위는 그 조건만 무효이다.","o":"법률행위 전부가 무효이다.","src":"민법 제151조 제1항 | 기출 2024-19"},{"x":"정지조건 있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다.","o":"정지조건은 성취한 때로부터 효력이 생긴다. 효력을 잃는 것은 해제조건이다.","src":"민법 제147조 | 기출 2024-20"},{"x":"조건이 법률행위의 당시에 이미 성취할 수 없는 불능조건인 경우에는 그 조건이 해제조건이면 그 법률행위는 무효로 한다.","o":"해제조건이면 조건 없는 법률행위가 된다.","src":"민법 제151조 제3항 | 기출 2024-20"},{"x":"종기(終期)있는 법률행위는 기한이 도래한 때로부터 그 효력이 생긴다.","o":"종기 있는 법률행위는 기한 도래 시부터 효력을 잃는다.","src":"민법 제152조 제2항 | 기출 2024-20"},{"x":"조건의 성취가 미정한 권리의무는 일반규정에 의하여 처분, 상속 또는 담보로 할 수 없다.","o":"일반규정에 의하여 처분, 상속, 보존 또는 담보로 할 수 있다.","src":"민법 제149조 | 기출 2024-20 | 기출 2025-20"},{"x":"해제조건이 있는 법률행위는 조건이 성취한 때부터 효력이 생긴다.","o":"해제조건이 성취한 때부터 효력을 잃는다.","src":"민법 제147조 제2항 | 기출 2025-20"},{"x":"선량한 풍속 기타 사회질서에 위반한 조건의 법률행위는 조건이 없는 법률행위이다.","o":"법률행위 전부가 무효이다.","src":"민법 제151조 제1항 | 기출 2025-20"},{"x":"해제조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우 그 법률행위는 무효이다.","o":"조건 없는 법률행위가 된다.","src":"민법 제151조 제3항 | 기출 2025-20"}]},"#17":{"묶음":[{"머리":"총칙과 기산점","줄":[{"t":"기간의 계산은 법령, 재판상의 처분 또는 법률행위에 다른 정한 바가 없으면 민법의 규정에 의한다.","src":"민법 제155조 | 기출 2025-21"},{"t":"민법의 기간에 관한 규정은 사법관계뿐 아니라 공법관계에도 적용된다.","src":"기출 2025-21"},{"t":"기간을 시·분·초로 정한 때에는 즉시로부터 기산한다.","src":"민법 제156조 | 기출 2021-22 | 기출 2022-21 | 기출 2024-21"},{"t":"기간을 일·주·월·연으로 정한 때에는 기간의 초일은 산입하지 아니한다(초일불산입). 그러나 그 기간이 오전 영시로부터 시작하는 때에는 초일을 산입한다.","src":"민법 제157조 | 기출 2022-21"},{"t":"초일불산입 원칙은 임의규정이다. 당사자의 합의로 달리 정할 수 있다.","src":"민법 제155조 | 기출 2023-22 | 기출 2025-21"},{"t":"기산점을 특정 날(오는 7월 1일부터)로 정한 때에는 그 날이 초일로 산입된다. ‘6월 1일부터 4일 동안’이면 기산점은 6월 1일이다.","src":"기출 2021-22 | 기출 2024-21 | 보충"},{"t":"나이는 출생일을 산입하여 만(滿) 나이로 계산하고 연수로 표시한다. 1세에 이르지 아니한 경우에는 월수로 표시할 수 있다.","src":"민법 제158조 | 기출 2022-21 | 기출 2024-21 | 기출 2025-21"},{"t":"2004년 5월 16일 출생자는 출생일을 산입하므로 2023년 5월 15일 24시에 19세(성년)가 된다.","src":"민법 제158조 | 민법 제4조 | 기출 2023-22 | 보충"},{"t":"정년 60세는 만 60세에 도달하는 날을 말하는 것으로 본다(만 60세가 만료되는 날이 아니다).","src":"기출 2021-22 | 기출 2024-21"}]},{"머리":"만료점","줄":[{"t":"기간을 일·주·월·연으로 정한 때에는 기간 말일의 종료로 기간이 만료한다.","src":"민법 제159조"},{"t":"기간을 주·월·연으로 정한 때에는 역(曆)에 의하여 계산한다.","src":"민법 제160조 제1항 | 기출 2022-21"},{"t":"주·월·연의 처음으로부터 기간을 기산하지 아니하는 때에는 최후의 주·월·연에서 그 기산일에 해당한 날의 전일로 기간이 만료한다.","src":"민법 제160조 제2항"},{"t":"월 또는 연으로 정한 경우에 최종의 월에 해당일이 없는 때에는 그 월의 말일로 기간이 만료한다.","src":"민법 제160조 제3항 | 기출 2021-22"},{"t":"기간의 말일이 토요일 또는 공휴일에 해당한 때에는 기간은 그 익일로 만료한다. 휴일이 연속되면 연속된 휴일의 다음 날이 만료일이다.","src":"민법 제161조 | 기출 2021-22 | 기출 2024-21 | 기출 2025-21"},{"t":"공휴일 특칙은 기간의 말일에만 적용된다. 초일이 공휴일이라고 기산을 다음 날로 미루지 않는다.","src":"민법 제161조 | 기출 2022-21"},{"t":"계산 예시: 6월 1일 14시부터 2일간이면 초일불산입으로 6월 2일 0시부터 시작하여 6월 3일 24시에 만료한다. 6월 1일 16시부터 72시간이면 6월 4일 16시에 만료한다. 4월 1일 09시부터 2개월이면 6월 1일 24시에 만료한다.","src":"민법 제156조 | 민법 제157조 | 민법 제160조 | 기출 2023-22"}]}],"함정":[{"x":"계약 기간의 기산점을 오는 7월 1일부터 기산하여 주(週)로 정한 때에는 기간의 초일은 산입하지 아니한다.","o":"기산점을 특정 날로 정한 때에는 그 날이 초일로 산입된다.","src":"기출 2021-22"},{"x":"기간의 초일(初日)이 공휴일에 해당한 때에는 기간은 그 익일부터 기산한다.","o":"공휴일 특칙은 기간의 말일에만 적용된다. 초일이 공휴일이라도 기산이 미뤄지지 않는다.","src":"민법 제161조 | 기출 2022-21"},{"x":"2023년 6월 1일(목) 14시부터 2일간의 기간이 만료하는 때는 2023년 6월 4일 24시이다.","o":"6월 3일 24시이다.","src":"기출 2023-22"},{"x":"2023년 4월 1일(토) 09시부터 2개월의 기간이 만료하는 때는 2023년 6월 2일 24시이다.","o":"6월 1일 24시이다.","src":"기출 2023-22"},{"x":"2004년 5월 16일(일) 오전 7시에 태어난 사람은 2023년 5월 16일 24시에 성년자가 된다.","o":"출생일을 산입하므로 2023년 5월 15일 24시에 성년이 된다.","src":"민법 제158조 | 기출 2023-22"},{"x":"민법 제157조의 초일불산입의 원칙은 강행규정이므로 당사자의 합의로 달리 정할 수 없다.","o":"임의규정이므로 합의로 달리 정할 수 있다.","src":"민법 제155조 | 기출 2023-22 | 기출 2025-21"},{"x":"정년이 60세라고 하는 것은 특별한 사정이 없으면 만60세가 만료되는 날을 말한다.","o":"만 60세에 도달하는 날을 말한다.","src":"기출 2024-21"},{"x":"기간을 일, 주, 월 또는 년으로 정한 때는 초일 불산입의 원칙이 적용되어 당사자간의 합의에 의해 이와 달리 정할 수 없다.","o":"합의로 달리 정할 수 있다.","src":"기출 2025-21"}]},"#18":{"묶음":[{"머리":"시효기간","줄":[{"t":"채권은 10년간 행사하지 아니하면 소멸시효가 완성한다.","src":"민법 제162조 제1항"},{"t":"채권 및 소유권 이외의 재산권은 20년간 행사하지 아니하면 소멸시효가 완성한다.","src":"민법 제162조 제2항 | 기출 2021-24"},{"t":"소유권과 점유권은 소멸시효에 걸리지 않는다. 소유권에 기한 물권적 청구권도 소멸시효에 걸리지 않는다.","src":"기출 2021-24 | 기출 2024-24 | 보충"},{"t":"3년의 단기소멸시효(제163조): ① 이자·부양료·급료·사용료 그 밖에 1년 이내의 기간으로 정한 금전 또는 물건의 지급을 목적으로 한 채권 ② 의사·조산사·간호사·약사의 치료·근로·조제에 관한 채권 ③ 도급받은 자·기사 그 밖에 공사의 설계 또는 감독에 종사하는 자의 공사에 관한 채권 ④ 변호사·변리사·공증인·공인회계사·법무사에 대한 직무상 보관한 서류의 반환을 청구하는 채권 ⑤ 변호사·변리사·공증인·공인회계사·법무사의 직무에 관한 채권 ⑥ 생산자 및 상인이 판매한 생산물 및 상품의 대가 ⑦ 수공업자 및 제조자의 업무에 관한 채권.","src":"민법 제163조 | 기출 2023-24 | 기출 2025-23"},{"t":"세무사의 직무에 관한 채권은 제163조에 열거된 3년의 단기소멸시효 대상이 아니다.","src":"기출 2023-24"},{"t":"1년의 단기소멸시효(제164조): ① 여관·음식점·대석·오락장의 숙박료·음식료·대석료·입장료·소비물의 대가 및 체당금의 채권 ② 의복·침구·장구 그 밖에 동산의 사용료의 채권 ③ 노역인·연예인의 임금 및 그에 공급한 물건의 대금채권 ④ 학생 및 수업자의 교육·의식 및 유숙에 관한 교주·숙주·교사의 채권.","src":"민법 제164조 | 기출 2022-23"},{"t":"판결에 의하여 확정된 채권은 단기의 소멸시효에 해당한 것이라도 그 소멸시효는 10년으로 한다. 파산절차에 의하여 확정된 채권 및 재판상의 화해·조정 그 밖에 판결과 동일한 효력이 있는 것에 의하여 확정된 채권도 같다.","src":"민법 제165조 제1항·제2항 | 기출 2022-23 | 기출 2024-24 | 기출 2025-23"},{"t":"판결확정 당시에 변제기가 도래하지 아니한 채권에는 10년 연장 규정이 적용되지 않는다.","src":"민법 제165조 제3항"},{"t":"상행위로 생긴 채권의 소멸시효는 다른 법령에 단기시효가 없으면 5년이다.","src":"상법 제64조 | 보충"},{"t":"불법행위로 인한 손해배상청구권: 피해자나 그 법정대리인이 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년.","src":"민법 제766조 | 기출 2021-2"}]},{"머리":"소멸시효의 효과","줄":[{"t":"소멸시효는 그 기산일에 소급하여 효력이 생긴다.","src":"민법 제167조 | 기출 2021-23 | 기출 2024-23 | 기출 2025-22"},{"t":"시효완성의 주장은 시효의 이익을 받는 자가 하여야 한다. 당사자가 시효완성의 항변을 하지 않으면 법원은 그 의사에 반하여 재판할 수 없다(변론주의).","src":"기출 2021-23 | 기출 2022-22"},{"t":"시효를 원용할 수 있는 자는 권리의 소멸에 의하여 직접 이익을 받는 사람에 한정된다.","src":"기출 2021-23"},{"t":"소멸시효기간이 몇 년인지는 법률 문제이므로 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다.","src":"기출 2023-23 | 보충"},{"t":"주된 권리의 소멸시효가 완성한 때에는 종속된 권리에 그 효력이 미친다.","src":"민법 제183조 | 기출 2024-23"},{"t":"소멸시효의 이익은 미리 포기하지 못한다.","src":"민법 제184조 제1항 | 기출 2024-23 | 기출 2025-22"},{"t":"소멸시효는 법률행위에 의하여 이를 배제, 연장 또는 가중할 수 없으나 이를 단축 또는 경감할 수 있다.","src":"민법 제184조 제2항 | 기출 2021-23 | 기출 2024-23"},{"t":"시효 완성 후 시효이익의 포기는 가능하다. 포기하면 포기한 때부터 그 채권의 소멸시효가 새로 진행한다.","src":"기출 2021-23 | 기출 2022-22 | 기출 2024-23"},{"t":"시효완성 후 채무자가 채무의 일부를 변제하면 시효이익의 포기로 본다.","src":"기출 2024-23"}]},{"머리":"소멸시효와 제척기간 비교","줄":[{"t":"소멸시효: 기산일에 소급하여 권리 소멸(소급효). 제척기간: 기간 경과 시부터 장래에 향하여 소멸.","src":"민법 제167조 | 기출 2022-22 | 기출 2025-22"},{"t":"소멸시효: 중단·정지가 있다. 제척기간: 중단이 없다.","src":"기출 2022-22 | 보충"},{"t":"소멸시효: 시효이익을 받은 자가 원용하여야 한다(변론주의). 제척기간: 도과 여부를 법원이 직권으로 조사한다.","src":"기출 2022-22 | 기출 2025-22"},{"t":"소멸시효: 완성 후 이익 포기 가능. 제척기간: 포기가 인정되지 않는다.","src":"기출 2022-22"},{"t":"제척기간의 기산점은 특별한 사정이 없는 한 권리가 발생한 때이다. 소멸시효는 권리를 행사할 수 있는 때이다.","src":"기출 2025-22 | 민법 제166조 제1항"},{"t":"청구권에 관하여 제척기간을 정하고 있더라도(예: 매도인의 하자담보책임에 기한 손해배상청구권) 그 청구권에 소멸시효 규정이 적용될 수 있다.","src":"기출 2022-22 | 보충"}]}],"함정":[{"x":"시효는 법률행위에 의하여 이를 배제하거나 경감할 수 없다.","o":"배제·연장·가중은 할 수 없지만 단축·경감은 할 수 있다.","src":"민법 제184조 제2항 | 기출 2021-23"},{"x":"소멸시효가 완성되면 그 기간이 경과한 때부터 장래에 향하여 권리가 소멸하지만, 제척기간이 완성되면 그 기산일에 소급하여 권리가 소멸한다.","o":"소멸시효는 기산일에 소급하여 소멸하고, 제척기간은 장래에 향하여 소멸한다.","src":"민법 제167조 | 기출 2022-22"},{"x":"소멸시효는 그 성질상 기간의 중단이 있을 수 없지만, 제척기간은 권리자의 청구가 있으면 기간이 중단된다.","o":"소멸시효에는 중단이 있고 제척기간에는 중단이 없다.","src":"기출 2022-22"},{"x":"소멸시효 완성에 의한 권리소멸은 법원의 직권조사 사항이지만, 제척기간에 의한 권리의 소멸은 원용권자가 이를 주장하여야 한다.","o":"소멸시효는 원용이 필요하고 제척기간은 직권조사 사항이다.","src":"기출 2022-22"},{"x":"매도인의 하자담보책임에 기한 매수인의 손해배상청구권과 같이 청구권에 관하여 제척기간을 정하고 있는 경우에는 제척기간이 적용되므로 소멸시효는 당연히 적용될 수 없다.","o":"제척기간이 있어도 소멸시효가 적용될 수 있다.","src":"기출 2022-22"},{"x":"소멸시효는 법률행위에 의하여 이를 배제할 수 없으나 연장할 수는 있다.","o":"배제·연장·가중 모두 할 수 없고, 단축·경감만 할 수 있다.","src":"민법 제184조 제2항 | 기출 2024-23"},{"x":"소멸시효의 이익은 미리 포기할 수 있다.","o":"미리 포기하지 못한다.","src":"민법 제184조 제1항 | 기출 2025-22"}]},"#19":{"묶음":[{"머리":"기산점 일반","줄":[{"t":"소멸시효는 권리를 행사할 수 있는 때로부터 진행한다.","src":"민법 제166조 제1항"},{"t":"부작위를 목적으로 하는 채권의 소멸시효는 위반행위를 한 때로부터 진행한다.","src":"민법 제166조 제2항 | 기출 2021-24 | 기출 2023-23 | 기출 2025-24"},{"t":"권리를 행사할 수 있는 때: 권리행사에 법률상의 장애사유가 없는 때를 말한다. 사실상의 장애(권리의 존재나 행사 가능성을 알지 못함, 채무자 무자력 등)는 포함되지 않는다.","src":"기출 2021-24 | 보충"},{"t":"정지조건부 권리는 조건이 성취된 때부터 시효가 진행된다.","src":"기출 2021-24"},{"t":"확정기한부 채권은 기한이 도래한 때(그 다음 날)부터 진행한다.","src":"보충"},{"t":"불확정기한부 채권은 그 기한이 객관적으로 도래한 때부터 진행한다.","src":"기출 2023-23"},{"t":"기한의 정함이 없는 채권은 채권이 성립한 때부터 진행한다.","src":"기출 2025-24"},{"t":"선택채권은 선택권을 행사할 수 있는 때부터 진행한다.","src":"기출 2023-23"},{"t":"동시이행의 항변권이 붙은 채권은 이행기부터 진행한다. 매매대금채권이 소유권이전등기청구권과 동시이행 관계에 있어도 지급기일 이후 시효가 진행한다.","src":"기출 2023-23 | 기출 2025-24"},{"t":"이행불능으로 인한 전보배상청구권은 이행불능 시부터 진행한다.","src":"기출 2025-24"},{"t":"형성권적 기한이익 상실 특약이 있는 할부채무는 1회 불이행만으로 전액에 대해 시효가 진행하지 않고, 채권자가 기한이익 상실의 의사표시(청구)를 한 때부터 전액에 대해 진행한다. 정지조건형 특약은 사유 발생 시 전액 진행한다.","src":"기출 2025-24 | 보충"}]},{"머리":"등기청구권 등","줄":[{"t":"매수인의 소유권이전등기청구권은 채권으로서 소멸시효에 걸린다. 그러나 매수인이 목적 부동산을 인도받아 점유·사용·수익하고 있는 동안에는 시효가 진행하지 않는다.","src":"기출 2022-24 | 기출 2024-24 | 보충"},{"t":"매수인이 점유를 상실한 때부터는 소유권이전등기청구권의 소멸시효가 진행한다.","src":"보충"},{"t":"소유권에 기한 말소등기청구권(물권적 청구권)은 소멸시효에 걸리지 않는다. 계약이 취소되어 매도인이 매수인에게 소유권에 기하여 말소등기를 청구하는 경우도 같다.","src":"기출 2022-24 | 기출 2024-24"},{"t":"점유권은 시효에 걸리지 아니한다.","src":"기출 2021-24 | 기출 2024-24"}]}],"함정":[{"x":"채권 및 소유권 이외의 재산권은 10년간 행사하지 아니하면 시효가 완성한다.","o":"20년이다. 채권은 10년이다.","src":"민법 제162조 | 기출 2021-24"},{"x":"어떤 권리의 소멸시효기간이 얼마나 되는지에 대해서는 법원이 직권으로 판단할 수 없다.","o":"법원이 직권으로 판단할 수 있다.","src":"기출 2023-23"},{"x":"부동산 매수인이 목적 부동산을 인도받아 계속 점유하고 있는 경우, 매수인의 소유권 이전등기청구권은 채권이므로 소멸시효가 진행한다.","o":"인도받아 점유하는 동안에는 소멸시효가 진행하지 않는다.","src":"기출 2024-24"},{"x":"형성권적 기한이익 상실의 특약이 있는 할부채무는 1회의 불이행시부터 바로 전액에 대해 소멸시효가 진행한다.","o":"채권자가 기한이익 상실의 의사표시를 한 때부터 전액에 대해 진행한다.","src":"기출 2025-24"}]},"#20":{"묶음":[{"머리":"중단사유(제168조)","줄":[{"t":"소멸시효의 중단사유: ① 청구 ② 압류 또는 가압류, 가처분 ③ 승인.","src":"민법 제168조"},{"t":"청구에 속하는 것: 재판상의 청구(제170조), 파산절차참가(제171조), 지급명령(제172조), 화해를 위한 소환·임의출석(제173조), 최고(제174조).","src":"민법 제170조 | 민법 제171조 | 민법 제172조 | 민법 제173조 | 민법 제174조"},{"t":"시효중단의 효력은 당사자 및 그 승계인 사이에만 있다(상대효).","src":"민법 제169조 | 기출 2021-25 | 기출 2024-24 | 기출 2025-25"},{"t":"중단 후 시효진행: 중단까지 경과한 시효기간은 산입하지 아니하고 중단사유가 종료한 때부터 새로이 진행한다. 재판상의 청구로 중단한 시효는 재판이 확정된 때부터 새로이 진행한다.","src":"민법 제178조 | 기출 2023-25 | 기출 2025-25"}]},{"머리":"청구","줄":[{"t":"재판상의 청구는 소송의 각하·기각 또는 취하의 경우에는 시효중단의 효력이 없다. 그러나 6월 내에 재판상의 청구, 파산절차참가, 압류 또는 가압류, 가처분을 한 때에는 시효는 최초의 재판상 청구로 인하여 중단된 것으로 본다.","src":"민법 제170조 | 기출 2025-25"},{"t":"파산절차참가는 채권자가 이를 취소하거나 그 청구가 각하된 때에는 시효중단의 효력이 없다.","src":"민법 제171조"},{"t":"지급명령은 채권자가 법정기간 내에 가집행신청을 하지 아니함으로 인하여 그 효력을 잃은 때에는 시효중단의 효력이 없다. 지급명령에 의한 시효중단의 효과는 지급명령을 신청한 때에 발생한다.","src":"민법 제172조 | 기출 2023-25"},{"t":"화해를 위한 소환은 상대방이 출석하지 아니하거나 화해가 성립되지 아니한 때에는 1월 내에 소를 제기하지 아니하면 시효중단의 효력이 없다. 임의출석의 경우에 화해가 성립되지 아니한 때에도 같다.","src":"민법 제173조 | 기출 2021-25 | 기출 2024-25"},{"t":"최고는 6월 내에 재판상의 청구, 파산절차참가, 화해를 위한 소환, 임의출석, 압류 또는 가압류, 가처분을 하지 아니하면 시효중단의 효력이 없다.","src":"민법 제174조"},{"t":"채무자가 제기한 소에 대하여 채권자가 응소하여 그 소송에서 적극적으로 권리를 주장하고 그것이 받아들여진 경우 재판상의 청구가 될 수 있다.","src":"기출 2021-25 | 기출 2024-25"},{"t":"승소 확정판결을 받은 채권자가 시효중단을 위해 후소를 제기하는 경우, 재판상 청구가 있다는 점에 대하여만 확인을 구하는 새로운 방식의 확인소송이 허용된다.","src":"기출 2024-25 | 보충"}]},{"머리":"압류·가압류·가처분","줄":[{"t":"압류, 가압류 및 가처분은 권리자의 청구에 의하여 또는 법률의 규정에 따르지 아니함으로 인하여 취소된 때에는 시효중단의 효력이 없다.","src":"민법 제175조"},{"t":"압류, 가압류 및 가처분은 시효의 이익을 받은 자에 대하여 하지 아니한 때에는 이를 그에게 통지한 후가 아니면 시효중단의 효력이 없다.","src":"민법 제176조 | 기출 2025-25"},{"t":"가압류의 피보전채권에 관하여 본안의 승소판결이 확정되어도 가압류에 의한 시효중단의 효력은 당연히 소멸하지 않는다(가압류 집행보전의 효력이 존속하는 동안 계속된다).","src":"기출 2023-25 | 보충"}]},{"머리":"승인","줄":[{"t":"시효중단의 효력 있는 승인에는 상대방의 권리에 관한 처분의 능력이나 권한 있음을 요하지 아니한다.","src":"민법 제177조 | 기출 2023-25 | 기출 2025-25"},{"t":"시효이익을 받을 본인의 대리인은 소멸시효 중단사유인 채무의 승인을 할 수 있다.","src":"기출 2023-25"},{"t":"시효완성 전에 한 채무의 일부변제는 특별한 사정이 없는 한 채무 승인으로서 시효중단사유가 될 수 있다.","src":"기출 2021-25"},{"t":"현존하지 않는 장래의 채권을 시효진행이 개시되기 전에 미리 승인하는 것은 허용되지 않는다.","src":"기출 2021-25 | 보충"}]},{"머리":"시효의 정지","줄":[{"t":"제한능력자: 소멸시효의 기간만료 전 6개월 내에 제한능력자에게 법정대리인이 없는 경우 그가 능력자가 되거나 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 아니한다.","src":"민법 제179조"},{"t":"재산을 관리하는 아버지·어머니 또는 후견인에 대한 제한능력자의 권리는 능력자가 되거나 후임 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 아니한다.","src":"민법 제180조 제1항"},{"t":"부부 중 한쪽이 다른 쪽에 대하여 가지는 권리는 혼인관계가 종료된 때부터 6개월 내에는 시효가 완성되지 아니한다.","src":"민법 제180조 제2항"},{"t":"상속재산에 속한 권리나 상속재산에 대한 권리는 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때부터 6개월 내에는 시효가 완성되지 아니한다.","src":"민법 제181조 | 기출 2024-25"},{"t":"천재 기타 사변으로 소멸시효를 중단할 수 없을 때에는 그 사유가 종료한 때부터 1개월 내에는 시효가 완성되지 아니한다.","src":"민법 제182조 | 기출 2024-25"}]}],"함정":[{"x":"현존하지 않는 장래의 채권을 시효진행이 개시되기 전에 미리 승인하는 것도 허용된다.","o":"허용되지 않는다.","src":"기출 2021-25"},{"x":"가압류의 피보전채권에 관하여 본안의 승소판결이 확정되면 가압류에 의한 시효중단의 효력은 당연히 소멸한다.","o":"당연히 소멸하지 않는다.","src":"기출 2023-25"},{"x":"승소 확정판결을 받은 채권자가 그 판결상 채권의 시효중단을 위해 후소를 제기하는 경우, 재판상 청구가 있다는 점에 대하여만 확인을 구하는 형태의 새로운 방식의 확인소송은 허용될 수 없다.","o":"이러한 확인소송도 허용된다.","src":"기출 2024-25"},{"x":"시효중단의 효력있는 승인은 상대방의 권리에 관한 처분의 능력이나 권한이 있음을 요한다.","o":"처분능력이나 권한 있음을 요하지 않는다.","src":"민법 제177조 | 기출 2025-25"}]}};
